const I18N={"fr":{"name":"Français","nav":{"home":"Accueil","support":"Support","privacy":"Confidentialité"},"home":{"lead":"Explorez chaque date à travers les calendriers, le Soleil, la Lune, l’histoire et l’astronomie. OmniDate 1.5.2 enrichit fortement les événements astronomiques avec les pluies de météores, les configurations planétaires, l’orbite terrestre, les comètes remarquables et de nouvelles représentations des éclipses passées et futures.","pills":["15 langues","≈ 20 000 événements historiques","Éclipses passées et futures","Pluies de météores","Comètes remarquables"],"cards":[["Une date, plusieurs calendriers","Comparez instantanément une même journée dans les calendriers grégorien, julien, républicain français, chinois, hébraïque, islamique, persan, bouddhiste, japonais et ISO 8601."],["Que s’est-il passé à cette date ?","Explorez une base locale d’environ 20 000 événements historiques. Filtrez par catégories, ouvrez un événement pour en consulter les détails et les sources, puis parcourez les événements d’un jour à l’autre."],["Événements astronomiques à venir","Retrouvez les saisons, phases lunaires, périgées, apogées, superlunes, éclipses, changements d’heure, pluies de météores, rapprochements planétaires, oppositions, élongations, périhélie, aphélie et passages de comètes remarquables."],["Pluies de météores","Pour les principales pluies de météores, visualisez les conditions géométriques d’observation sur une carte et examinez le potentiel depuis le lieu sélectionné."],["Éclipses dans le temps et l’espace","Explorez les éclipses solaires et lunaires, futures comme passées. Les cartes dédiées montrent les zones de visibilité et, selon le phénomène, la trajectoire, les limites et les circonstances locales."],["Lune et événements lunaires","Phase lunaire, illumination, âge de la Lune, distance Terre-Lune, lever et coucher, altitude, azimut et prochains événements lunaires."],["Suivez la course du Soleil","Lever et coucher du Soleil, midi solaire, durée du jour, progression de la journée ou de la nuit et crépuscules civil, nautique et astronomique."],["Éphéméride et astrologie","Retrouvez les fêtes de prénoms, dictons et journées internationales disponibles, ainsi que les informations astrologiques proposées par OmniDate."],["Fiches de date en PDF","Créez une fiche à partir d’une date, d’une heure et d’un lieu. Réunissez calendriers, Soleil, Lune, éphéméride et astrologie, puis enregistrez ou partagez le résultat en PDF."],["Dates favorites","Enregistrez vos dates importantes, retrouvez-les rapidement et activez si vous le souhaitez une notification annuelle."],["Widgets personnalisables","Configurez les widgets d’écran d’accueil et d’écran verrouillé pour afficher les calendriers et informations qui vous intéressent."],["Apple Watch","Retrouvez les informations essentielles d’OmniDate au poignet et utilisez les complications dédiées."]]},"privacy":{"title":"Politique de confidentialité","updated":"Dernière mise à jour : 19 octobre 2026","notice":"OmniDate 1.5.2 est conçue pour fonctionner sans compte utilisateur, sans publicité, sans suivi inter-apps et sans collecte de données personnelles par l’éditeur.","sections":[["1. Données collectées par OmniDate",["OmniDate ne demande pas la création d’un compte et ne collecte, ne stocke ni ne transmet de données personnelles vers un serveur exploité par l’éditeur."]],["2. Données enregistrées localement",["Les réglages de l’application et les informations que vous choisissez d’enregistrer, notamment les dates favorites, leur nom, les préférences d’affichage, les réglages des calendriers, de l’éphéméride et des notifications, sont conservés localement sur votre appareil."]],["3. Calculs calendaires et astronomiques",["Les conversions de calendriers et la majorité des calculs liés au Soleil, à la Lune, aux planètes, aux éclipses, aux pluies de météores, à l’orbite terrestre et aux autres événements astronomiques sont effectués localement sur l’appareil. Les données intégrées à OmniDate sont consultées localement."]],["4. Événements historiques et traduction",["OmniDate comprend une base locale d’environ 20 000 événements historiques. Leur consultation, filtrage et navigation sont effectués sur l’appareil. Les liens Wikipedia/Wikimedia ne sont ouverts que lorsque vous choisissez de les consulter.","Pour certaines langues, OmniDate peut s’appuyer sur les fonctions de traduction d’Apple. L’éditeur ne reçoit ni les textes traduits ni les requêtes de traduction."]],["5. Fiches de date et PDF",["OmniDate peut créer une fiche à partir d’une date, d’une heure, d’un lieu et, si vous le souhaitez, d’un titre. Ces informations sont utilisées localement. Le partage d’un PDF utilise les fonctions de partage d’iOS ou d’iPadOS et le service que vous choisissez."]],["6. Localisation et recherche de lieux",["Lorsque vous choisissez d’utiliser votre position actuelle, OmniDate accède à la localisation afin de calculer les informations dépendant du lieu, notamment les données solaires, certaines données lunaires, la visibilité locale des éclipses et certaines conditions d’observation astronomique.","OmniDate ne transmet pas votre position à un serveur exploité par l’éditeur. Des services système d’Apple peuvent être utilisés pour rechercher un lieu ou associer un nom de ville à des coordonnées. Vous pouvez aussi utiliser un lieu enregistré ou une ville sélectionnée manuellement."]],["7. Siri et App Intents",["OmniDate peut utiliser Siri et App Intents pour certaines informations solaires. OmniDate n’exploite aucun serveur propre pour traiter ces requêtes."]],["8. Apple Watch",["OmniDate propose des fonctions Apple Watch et des complications. L’éditeur ne collecte pas de données personnelles supplémentaires du fait de leur utilisation."]],["9. Notifications",["OmniDate peut programmer des notifications locales pour certains événements ainsi que des rappels annuels associés aux dates favorites. Elles sont planifiées sur l’appareil selon vos réglages."]],["10. Widgets",["Les widgets d’écran d’accueil et d’écran verrouillé utilisent les informations nécessaires au fonctionnement d’OmniDate sur l’appareil. Leur utilisation ne donne lieu à aucune collecte de données personnelles par l’éditeur."]],["11. Suivi, publicité et profilage",["OmniDate n’intègre pas de publicité, ne réalise pas de suivi inter-apps et ne crée pas de profil utilisateur à des fins publicitaires."]],["12. Services Apple",["Apple peut traiter certaines informations techniques conformément à ses propres politiques et aux réglages choisis par l’utilisateur. Ces traitements relèvent des services Apple."]],["13. Liens externes",["OmniDate et son site de support peuvent contenir des liens vers Wikipedia, Wikimedia, GitHub ou d’autres services externes. Leur utilisation est soumise à leurs propres politiques de confidentialité."]],["14. Enfants",["OmniDate ne collecte pas sciemment de données personnelles concernant des enfants ou d’autres utilisateurs."]],["15. Modification de cette politique",["Cette politique pourra être mise à jour si les fonctionnalités d’OmniDate évoluent."]],["16. Contact",["Pour toute question, utilisez la page de support OmniDate."]]]},"support":{"title":"Support","intro":"Vous rencontrez un problème avec OmniDate, souhaitez signaler une erreur ou proposer une amélioration ? Cette page est le point de contact officiel pour l’assistance liée à l’application.","contact":"Contact","contactp":"Pour toute demande d’assistance, écrivez à","report":"Signaler un problème","view":"Voir les signalements","before":"Avant de signaler un problème","bullets":["indiquez le modèle de votre iPhone, iPad ou Apple Watch ;","indiquez la version d’iOS, d’iPadOS ou de watchOS ;","précisez la version d’OmniDate ;","décrivez les étapes permettant de reproduire le problème ;","pour un problème d’affichage, précisez le modèle d’appareil et son orientation ;","pour une éclipse ou une pluie de météores, indiquez la date et le lieu sélectionné ;","pour un événement historique, indiquez la date, la langue et si possible son titre."],"notice":"Pour votre sécurité, ne publiez jamais d’informations personnelles, de mots de passe ou de données confidentielles dans un ticket public.","faqtitle":"Questions fréquentes","faqs":[["Que contient « Événements à venir » dans OmniDate 1.5.2 ?","La rubrique regroupe les saisons, phases lunaires, périgées, apogées, superlunes, éclipses solaires et lunaires, changements d’heure, pluies de météores, rapprochements et oppositions planétaires, élongations de Mercure et Vénus, périhélie et aphélie terrestres ainsi que les passages de comètes remarquables."],["Peut-on explorer les éclipses du passé ?","Oui. OmniDate est conçu pour explorer les dates passées comme futures. Les cartes permettent donc d’étudier des éclipses historiques lorsque les données nécessaires sont disponibles."],["Que montrent les cartes d’éclipses ?","Selon le type d’éclipse, elles peuvent afficher les zones de visibilité, la trajectoire ou les limites du phénomène, son maximum approximatif et les circonstances calculées pour un point sélectionné."],["Que montre la carte d’une pluie de météores ?","Elle représente les conditions géométriques d’observation selon la position du radiant, l’obscurité du ciel et l’influence de la Lune. Il s’agit d’une aide à l’observation, pas d’une prévision météorologique."],["Que contient « Que s’est-il passé à cette date ? » ?","OmniDate intègre une base locale d’environ 20 000 événements historiques. Ils peuvent être filtrés par catégorie, ouverts individuellement et parcourus jour par jour dans la vue complète."],["Comment créer une fiche de date en PDF ?","Touchez le bouton de partage puis choisissez « Créer une fiche de date ». Indiquez la date, l’heure et le lieu, sélectionnez les calendriers, puis prévisualisez la fiche avant de l’enregistrer ou de la partager."],["À quoi sert la localisation ?","Elle est utilisée pour les données dépendant du lieu : horaires solaires, certaines informations lunaires, visibilité locale des éclipses et certaines conditions d’observation astronomique. Vous pouvez utiliser votre position actuelle, un lieu enregistré ou une ville choisie manuellement."],["OmniDate nécessite-t-elle un compte ?","Non. Aucun compte utilisateur n’est nécessaire."]]},"rtl":false},"en":{"name":"English","nav":{"home":"Home","support":"Support","privacy":"Privacy"},"home":{"lead":"Explore every date through calendars, the Sun, the Moon, history and astronomy. OmniDate 1.5.2 greatly expands astronomical events with meteor showers, planetary configurations, Earth-orbit events, notable comets and new visualisations of both past and future eclipses.","pills":["15 languages","≈ 20,000 historical events","Past and future eclipses","Meteor showers","Notable comets"],"cards":[["One date, multiple calendars","Instantly compare the same day across Gregorian, Julian, French Republican, Chinese, Hebrew, Islamic, Persian, Buddhist, Japanese and ISO 8601 calendars."],["What happened on this date?","Explore a local database of about 20,000 historical events. Filter by category, open an event to view details and sources, then browse events day by day."],["Upcoming astronomical events","View seasons, Moon phases, perigees, apogees, supermoons, eclipses, civil-time changes, meteor showers, planetary conjunctions, oppositions, elongations, perihelion, aphelion and notable comet passages."],["Meteor showers","For major meteor showers, visualise geometric observing conditions on a map and examine the observing potential from the selected location."],["Eclipses across time and space","Explore solar and lunar eclipses, both future and historical. Dedicated maps show visibility areas and, depending on the event, the path, boundaries and local circumstances."],["Moon and lunar events","Moon phase, illumination, Moon age, Earth-Moon distance, moonrise, moonset, altitude, azimuth and upcoming lunar events."],["Follow the Sun","Sunrise, sunset, solar noon, day length, daytime or nighttime progress, plus civil, nautical and astronomical twilight."],["Ephemeris and astrology","View available name days, traditional sayings and international observances, together with the astrology information provided by OmniDate."],["PDF date sheets","Create a date sheet from a date, time and place. Bring together calendars, Sun, Moon, ephemeris and astrology, then save or share the result as a PDF."],["Favourite dates","Save important dates, return to them quickly and optionally enable an annual notification."],["Customisable widgets","Configure Home Screen and Lock Screen widgets to display the calendars and information that matter to you."],["Apple Watch","Access essential OmniDate information on your wrist and use dedicated complications."]]},"privacy":{"title":"Privacy Policy","updated":"Last updated: October 19, 2026","notice":"OmniDate 1.5.2 is designed to work without a user account, advertising, cross-app tracking or personal-data collection by the developer.","sections":[["1. Data collected by OmniDate",["OmniDate does not require an account and does not collect, store or transmit personal data to a server operated by the developer."]],["2. Data stored locally",["App settings and information you choose to save, including favourite dates, their names, display preferences, calendar settings, ephemeris settings and notification preferences, are stored locally on your device."]],["3. Calendar and astronomical calculations",["Calendar conversions and most calculations related to the Sun, Moon, planets, eclipses, meteor showers, Earth orbit and other astronomical events are performed locally on the device. Data bundled with OmniDate is accessed locally."]],["4. Historical events and translation",["OmniDate includes a local database of about 20,000 historical events. Browsing, filtering and navigation are handled on the device. Wikipedia/Wikimedia links are opened only when you choose to follow them.","For some languages, OmniDate may rely on Apple’s translation features. The developer does not receive translated text or translation requests."]],["5. Date sheets and PDF files",["OmniDate can create a date sheet from a date, time, place and, if you choose, a title. This information is used locally. PDF sharing uses the sharing features provided by iOS or iPadOS and the service you select."]],["6. Location and place search",["When you choose to use your current location, OmniDate accesses device location to calculate location-dependent information, including solar data, selected lunar data, local eclipse visibility and certain astronomical observing conditions.","OmniDate does not send your location to a server operated by the developer. Apple system services may be used to search for a place or associate a city name with coordinates. You may also use a saved place or manually selected city."]],["7. Siri and App Intents",["OmniDate can use Siri and App Intents for selected solar information. OmniDate does not use its own server to process these requests."]],["8. Apple Watch",["OmniDate includes Apple Watch features and complications. The developer does not collect additional personal data as a result of their use."]],["9. Notifications",["OmniDate can schedule local notifications for selected events and annual reminders for favourite dates. They are scheduled on the device according to your settings."]],["10. Widgets",["Home Screen and Lock Screen widgets use the information required for OmniDate to operate on the device. Their use does not result in personal-data collection by the developer."]],["11. Tracking, advertising and profiling",["OmniDate does not include advertising, does not perform cross-app tracking and does not create advertising profiles."]],["12. Apple services",["Apple may process certain technical information in accordance with its own policies and the settings selected by the user. Such processing is part of Apple services."]],["13. External links",["OmniDate and its support website may contain links to Wikipedia, Wikimedia, GitHub or other external services. Their use is subject to their own privacy policies."]],["14. Children",["OmniDate does not knowingly collect personal data from children or other users."]],["15. Changes to this policy",["This policy may be updated as OmniDate’s features evolve."]],["16. Contact",["For questions, please use the OmniDate support page."]]]},"support":{"title":"Support","intro":"Having an issue with OmniDate, found an error, or want to suggest an improvement? This page is the official support point for the app.","contact":"Contact","contactp":"For support requests, email","report":"Report an issue","view":"View issues","before":"Before reporting an issue","bullets":["include your iPhone, iPad or Apple Watch model;","include your iOS, iPadOS or watchOS version;","include your OmniDate version;","describe the steps needed to reproduce the issue;","for a display issue, include the device model and orientation;","for an eclipse or meteor-shower issue, include the date and selected location;","for a historical-event issue, include the date, selected language and, if possible, its title."],"notice":"For your safety, never post personal information, passwords or confidential data in a public issue.","faqtitle":"Frequently asked questions","faqs":[["What is included in Upcoming Events in OmniDate 1.5.2?","It includes seasons, Moon phases, perigees, apogees, supermoons, solar and lunar eclipses, civil-time changes, meteor showers, planetary conjunctions and oppositions, Mercury and Venus elongations, Earth perihelion and aphelion, and notable comet passages."],["Can I explore eclipses from the past?","Yes. OmniDate is designed to explore both past and future dates. Eclipse maps can therefore be used to study historical eclipses when the required data is available."],["What do the eclipse maps show?","Depending on the eclipse type, maps may show visibility areas, the eclipse path or boundaries, an approximate maximum point and calculated circumstances for a selected location."],["What does a meteor-shower map show?","It represents geometric observing conditions based on radiant position, sky darkness and Moon interference. It is an observing aid, not a weather forecast."],["What is included in “What happened on this date?”","OmniDate includes a local database of about 20,000 historical events. Events can be filtered by category, opened individually and browsed day by day in the full list."],["How do I create a PDF date sheet?","Tap the Share button and choose “Create a date sheet”. Enter the date, time and place, select calendars, then preview the sheet before saving or sharing it."],["Why does OmniDate use location?","Location is used for place-dependent information: solar times, selected lunar information, local eclipse visibility and certain astronomical observing conditions. You can use your current position, a saved place or a manually selected city."],["Does OmniDate require an account?","No. No user account is required."]]},"rtl":false},"de":{"name":"Deutsch","nav":{"home":"Startseite","support":"Support","privacy":"Datenschutz"},"home":{"lead":"Entdecken Sie jedes Datum über Kalender, Sonne, Mond, Geschichte und Astronomie. OmniDate 1.5.2 erweitert die astronomischen Ereignisse deutlich um Meteorschauer, Planetenkonstellationen, Ereignisse der Erdbahn, bemerkenswerte Kometen sowie neue Darstellungen vergangener und zukünftiger Finsternisse.","pills":["15 Sprachen","≈ 20.000 historische Ereignisse","Vergangene und zukünftige Finsternisse","Meteorschauer","Bemerkenswerte Kometen"],"cards":[["Ein Datum, mehrere Kalender","Vergleichen Sie denselben Tag sofort im gregorianischen, julianischen, französisch-republikanischen, chinesischen, hebräischen, islamischen, persischen, buddhistischen und japanischen Kalender sowie nach ISO 8601."],["Was geschah an diesem Datum?","Erkunden Sie eine lokale Datenbank mit rund 20.000 historischen Ereignissen. Filtern Sie nach Kategorien, öffnen Sie einzelne Ereignisse mit Details und Quellen und blättern Sie Tag für Tag."],["Kommende astronomische Ereignisse","Jahreszeiten, Mondphasen, Perigäum, Apogäum, Supermonde, Finsternisse, Zeitumstellungen, Meteorschauer, Planetenkonjunktionen, Oppositionen, Elongationen, Perihel, Aphel und bemerkenswerte Kometenpassagen."],["Meteorschauer","Für die wichtigsten Meteorschauer können Sie geometrische Beobachtungsbedingungen auf einer Karte anzeigen und das Beobachtungspotenzial am gewählten Ort prüfen."],["Finsternisse in Raum und Zeit","Erkunden Sie zukünftige und historische Sonnen- und Mondfinsternisse. Spezielle Karten zeigen Sichtbarkeitsgebiete und je nach Ereignis Verlauf, Grenzen und lokale Umstände."],["Mond und Mondereignisse","Mondphase, Beleuchtung, Mondalter, Erde-Mond-Entfernung, Mondaufgang und -untergang, Höhe, Azimut und kommende Mondereignisse."],["Folgen Sie dem Lauf der Sonne","Sonnenaufgang, Sonnenuntergang, Sonnenmittag, Tageslänge, Fortschritt von Tag oder Nacht sowie bürgerliche, nautische und astronomische Dämmerung."],["Ephemeriden und Astrologie","Sehen Sie verfügbare Namenstage, traditionelle Sprüche und internationale Gedenktage sowie die von OmniDate bereitgestellten astrologischen Informationen."],["Datumsblätter als PDF","Erstellen Sie ein Datumsblatt aus Datum, Uhrzeit und Ort. Fassen Sie Kalender, Sonne, Mond, Ephemeriden und Astrologie zusammen und speichern oder teilen Sie das Ergebnis als PDF."],["Favorisierte Daten","Speichern Sie wichtige Daten, rufen Sie sie schnell wieder auf und aktivieren Sie auf Wunsch eine jährliche Benachrichtigung."],["Anpassbare Widgets","Konfigurieren Sie Widgets für Home-Bildschirm und Sperrbildschirm mit den Kalendern und Informationen, die Sie interessieren."],["Apple Watch","Rufen Sie wichtige OmniDate-Informationen am Handgelenk ab und nutzen Sie die passenden Komplikationen."]]},"privacy":{"title":"Datenschutzerklärung","updated":"Letzte Aktualisierung: 19. Oktober 2026","notice":"OmniDate 1.5.2 ist für die Nutzung ohne Benutzerkonto, Werbung, appübergreifendes Tracking oder Erfassung personenbezogener Daten durch den Entwickler ausgelegt.","sections":[["1. Von OmniDate erfasste Daten",["OmniDate erfordert kein Konto und erfasst, speichert oder überträgt keine personenbezogenen Daten an einen vom Entwickler betriebenen Server."]],["2. Lokal gespeicherte Daten",["App-Einstellungen und von Ihnen gespeicherte Informationen, darunter Favoritendaten, Namen, Anzeigeeinstellungen, Kalender-, Ephemeriden- und Benachrichtigungseinstellungen, werden lokal auf Ihrem Gerät gespeichert."]],["3. Kalender- und astronomische Berechnungen",["Kalenderumrechnungen und die meisten Berechnungen zu Sonne, Mond, Planeten, Finsternissen, Meteorschauern, Erdbahn und anderen astronomischen Ereignissen erfolgen lokal auf dem Gerät. In OmniDate enthaltene Daten werden lokal genutzt."]],["4. Historische Ereignisse und Übersetzung",["OmniDate enthält eine lokale Datenbank mit etwa 20.000 historischen Ereignissen. Anzeige, Filterung und Navigation erfolgen auf dem Gerät. Wikipedia/Wikimedia-Links werden nur geöffnet, wenn Sie dies auswählen.","Für einige Sprachen kann OmniDate Apples Übersetzungsfunktionen nutzen. Der Entwickler erhält weder übersetzte Texte noch Übersetzungsanfragen."]],["5. Datumsblätter und PDF-Dateien",["OmniDate kann aus Datum, Uhrzeit, Ort und optional einem Titel ein Datumsblatt erstellen. Diese Informationen werden lokal verwendet. Das Teilen von PDFs erfolgt über die Freigabefunktionen von iOS oder iPadOS und den von Ihnen gewählten Dienst."]],["6. Standort und Ortssuche",["Wenn Sie Ihren aktuellen Standort verwenden, greift OmniDate auf den Gerätestandort zu, um ortsabhängige Informationen wie Sonnendaten, ausgewählte Monddaten, lokale Finsternissichtbarkeit und bestimmte astronomische Beobachtungsbedingungen zu berechnen.","OmniDate sendet Ihren Standort nicht an einen Server des Entwicklers. Apple-Systemdienste können zur Ortssuche oder Zuordnung eines Städtenamens zu Koordinaten verwendet werden. Sie können auch einen gespeicherten Ort oder eine manuell gewählte Stadt verwenden."]],["7. Siri und App Intents",["OmniDate kann Siri und App Intents für ausgewählte Sonneninformationen verwenden. OmniDate nutzt keinen eigenen Server zur Verarbeitung dieser Anfragen."]],["8. Apple Watch",["OmniDate bietet Apple-Watch-Funktionen und Komplikationen. Durch deren Nutzung erfasst der Entwickler keine zusätzlichen personenbezogenen Daten."]],["9. Benachrichtigungen",["OmniDate kann lokale Benachrichtigungen für ausgewählte Ereignisse und jährliche Erinnerungen für Favoritendaten planen. Sie werden entsprechend Ihren Einstellungen auf dem Gerät geplant."]],["10. Widgets",["Widgets auf Home-Bildschirm und Sperrbildschirm verwenden die für OmniDate auf dem Gerät erforderlichen Informationen. Ihre Nutzung führt nicht zur Erfassung personenbezogener Daten durch den Entwickler."]],["11. Tracking, Werbung und Profiling",["OmniDate enthält keine Werbung, führt kein appübergreifendes Tracking durch und erstellt keine Werbeprofile."]],["12. Apple-Dienste",["Apple kann bestimmte technische Informationen gemäß seinen eigenen Richtlinien und den Benutzereinstellungen verarbeiten. Diese Verarbeitung gehört zu den Apple-Diensten."]],["13. Externe Links",["OmniDate und seine Support-Website können Links zu Wikipedia, Wikimedia, GitHub oder anderen externen Diensten enthalten. Für deren Nutzung gelten die jeweiligen Datenschutzrichtlinien."]],["14. Kinder",["OmniDate erfasst wissentlich keine personenbezogenen Daten von Kindern oder anderen Nutzern."]],["15. Änderungen dieser Richtlinie",["Diese Richtlinie kann aktualisiert werden, wenn sich die Funktionen von OmniDate weiterentwickeln."]],["16. Kontakt",["Bei Fragen verwenden Sie bitte die OmniDate-Supportseite."]]]},"support":{"title":"Hilfe","intro":"Haben Sie ein Problem mit OmniDate, einen Fehler gefunden oder einen Verbesserungsvorschlag? Diese Seite ist die offizielle Support-Anlaufstelle für die App.","contact":"Kontakt","contactp":"Für Support-Anfragen schreiben Sie an","report":"Problem melden","view":"Meldungen anzeigen","before":"Vor dem Melden eines Problems","bullets":["geben Sie Ihr iPhone-, iPad- oder Apple-Watch-Modell an;","geben Sie Ihre iOS-, iPadOS- oder watchOS-Version an;","geben Sie Ihre OmniDate-Version an;","beschreiben Sie die Schritte zum Reproduzieren des Problems;","bei Anzeigeproblemen geben Sie Gerätemodell und Ausrichtung an;","bei Finsternis- oder Meteorschauerproblemen geben Sie Datum und gewählten Ort an;","bei historischen Ereignissen geben Sie Datum, Sprache und möglichst den Titel an."],"notice":"Veröffentlichen Sie zu Ihrer Sicherheit niemals persönliche Informationen, Passwörter oder vertrauliche Daten in einem öffentlichen Ticket.","faqtitle":"Häufig gestellte Fragen","faqs":[["Was enthält „Kommende Ereignisse“ in OmniDate 1.5.2?","Jahreszeiten, Mondphasen, Perigäum, Apogäum, Supermonde, Sonnen- und Mondfinsternisse, Zeitumstellungen, Meteorschauer, Planetenkonjunktionen und -oppositionen, Elongationen von Merkur und Venus, Perihel und Aphel der Erde sowie bemerkenswerte Kometenpassagen."],["Kann ich Finsternisse der Vergangenheit erkunden?","Ja. OmniDate ist für vergangene und zukünftige Daten ausgelegt. Finsterniskarten können daher historische Finsternisse zeigen, wenn die erforderlichen Daten verfügbar sind."],["Was zeigen die Finsterniskarten?","Je nach Finsternistyp können sie Sichtbarkeitsgebiete, Verlauf oder Grenzen des Phänomens, einen ungefähren Maximalpunkt und berechnete Umstände für einen gewählten Ort zeigen."],["Was zeigt eine Meteorschauerkarte?","Sie stellt geometrische Beobachtungsbedingungen anhand von Radiantenposition, Himmelsdunkelheit und Mondeinfluss dar. Sie ist eine Beobachtungshilfe, keine Wettervorhersage."],["Was enthält „Was geschah an diesem Datum?“","OmniDate enthält eine lokale Datenbank mit etwa 20.000 historischen Ereignissen. Sie können nach Kategorie gefiltert, einzeln geöffnet und in der vollständigen Ansicht Tag für Tag durchsucht werden."],["Wie erstelle ich ein PDF-Datumsblatt?","Tippen Sie auf „Teilen“ und wählen Sie „Datumsblatt erstellen“. Geben Sie Datum, Uhrzeit und Ort ein, wählen Sie Kalender und prüfen Sie das Blatt vor dem Speichern oder Teilen."],["Warum verwendet OmniDate den Standort?","Der Standort wird für ortsabhängige Informationen verwendet: Sonnenzeiten, ausgewählte Monddaten, lokale Finsternissichtbarkeit und bestimmte astronomische Beobachtungsbedingungen. Sie können den aktuellen Standort, einen gespeicherten Ort oder eine manuell gewählte Stadt verwenden."],["Benötigt OmniDate ein Konto?","Nein. Es ist kein Benutzerkonto erforderlich."]]},"rtl":false},"es":{"name":"Español","nav":{"home":"Inicio","support":"Soporte","privacy":"Privacidad"},"home":{"lead":"Explora cada fecha a través de los calendarios, el Sol, la Luna, la historia y la astronomía. OmniDate 1.5.2 amplía notablemente los eventos astronómicos con lluvias de meteoros, configuraciones planetarias, eventos de la órbita terrestre, cometas destacados y nuevas representaciones de eclipses pasados y futuros.","pills":["15 idiomas","≈ 20.000 eventos históricos","Eclipses pasados y futuros","Lluvias de meteoros","Cometas destacados"],"cards":[["Una fecha, varios calendarios","Compara al instante el mismo día en los calendarios gregoriano, juliano, republicano francés, chino, hebreo, islámico, persa, budista, japonés e ISO 8601."],["¿Qué ocurrió en esta fecha?","Explora una base local de unos 20.000 acontecimientos históricos. Filtra por categorías, abre un evento para consultar detalles y fuentes y recorre los eventos día a día."],["Próximos eventos astronómicos","Consulta estaciones, fases lunares, perigeos, apogeos, superlunas, eclipses, cambios de hora, lluvias de meteoros, conjunciones planetarias, oposiciones, elongaciones, perihelio, afelio y pasos de cometas destacados."],["Lluvias de meteoros","Para las principales lluvias de meteoros, visualiza en un mapa las condiciones geométricas de observación y examina el potencial desde el lugar seleccionado."],["Eclipses en el tiempo y el espacio","Explora eclipses solares y lunares, tanto futuros como históricos. Los mapas muestran las zonas de visibilidad y, según el fenómeno, la trayectoria, los límites y las circunstancias locales."],["Luna y eventos lunares","Fase lunar, iluminación, edad de la Luna, distancia Tierra-Luna, salida y puesta, altitud, acimut y próximos eventos lunares."],["Sigue el recorrido del Sol","Salida y puesta del Sol, mediodía solar, duración del día, progreso del día o la noche y crepúsculos civil, náutico y astronómico."],["Efemérides y astrología","Consulta santoral, refranes y días internacionales disponibles, junto con la información astrológica ofrecida por OmniDate."],["Fichas de fecha en PDF","Crea una ficha a partir de una fecha, hora y lugar. Reúne calendarios, Sol, Luna, efemérides y astrología y guarda o comparte el resultado en PDF."],["Fechas favoritas","Guarda tus fechas importantes, vuelve a ellas rápidamente y activa, si quieres, una notificación anual."],["Widgets personalizables","Configura los widgets de pantalla de inicio y bloqueo para mostrar los calendarios y la información que te interesan."],["Apple Watch","Consulta la información esencial de OmniDate en tu muñeca y utiliza sus complicaciones."]]},"privacy":{"title":"Política de privacidad","updated":"Última actualización: 19 de octubre de 2026","notice":"OmniDate 1.5.2 está diseñada para funcionar sin cuenta de usuario, publicidad, seguimiento entre apps ni recopilación de datos personales por parte del desarrollador.","sections":[["1. Datos recopilados por OmniDate",["OmniDate no requiere una cuenta y no recopila, almacena ni transmite datos personales a un servidor operado por el desarrollador."]],["2. Datos almacenados localmente",["Los ajustes de la app y la información que decides guardar, incluidas fechas favoritas, nombres, preferencias de visualización, ajustes de calendarios, efemérides y notificaciones, se almacenan localmente en tu dispositivo."]],["3. Cálculos calendáricos y astronómicos",["Las conversiones de calendarios y la mayoría de cálculos sobre el Sol, la Luna, los planetas, eclipses, lluvias de meteoros, órbita terrestre y otros eventos astronómicos se realizan localmente en el dispositivo. Los datos incluidos en OmniDate se consultan localmente."]],["4. Eventos históricos y traducción",["OmniDate incluye una base local de unos 20.000 eventos históricos. La consulta, filtrado y navegación se realizan en el dispositivo. Los enlaces de Wikipedia/Wikimedia solo se abren cuando decides hacerlo.","Para algunos idiomas, OmniDate puede utilizar las funciones de traducción de Apple. El desarrollador no recibe los textos traducidos ni las solicitudes de traducción."]],["5. Fichas de fecha y PDF",["OmniDate puede crear una ficha a partir de una fecha, hora, lugar y, si quieres, un título. Esta información se utiliza localmente. Compartir un PDF utiliza las funciones de iOS o iPadOS y el servicio que elijas."]],["6. Ubicación y búsqueda de lugares",["Cuando eliges usar tu ubicación actual, OmniDate accede a ella para calcular información dependiente del lugar, incluidos datos solares, determinados datos lunares, visibilidad local de eclipses y ciertas condiciones de observación astronómica.","OmniDate no envía tu ubicación a un servidor del desarrollador. Los servicios del sistema de Apple pueden utilizarse para buscar un lugar o asociar un nombre de ciudad a coordenadas. También puedes usar un lugar guardado o una ciudad seleccionada manualmente."]],["7. Siri y App Intents",["OmniDate puede utilizar Siri y App Intents para determinada información solar. OmniDate no utiliza un servidor propio para procesar estas solicitudes."]],["8. Apple Watch",["OmniDate incluye funciones y complicaciones para Apple Watch. El desarrollador no recopila datos personales adicionales por su uso."]],["9. Notificaciones",["OmniDate puede programar notificaciones locales para determinados eventos y recordatorios anuales de fechas favoritas. Se programan en el dispositivo según tus ajustes."]],["10. Widgets",["Los widgets de pantalla de inicio y bloqueo utilizan la información necesaria para que OmniDate funcione en el dispositivo. Su uso no genera recopilación de datos personales por parte del desarrollador."]],["11. Seguimiento, publicidad y perfilado",["OmniDate no incluye publicidad, no realiza seguimiento entre apps y no crea perfiles publicitarios."]],["12. Servicios de Apple",["Apple puede procesar determinada información técnica conforme a sus propias políticas y a los ajustes elegidos por el usuario. Ese tratamiento forma parte de los servicios de Apple."]],["13. Enlaces externos",["OmniDate y su sitio de soporte pueden contener enlaces a Wikipedia, Wikimedia, GitHub u otros servicios externos. Su uso está sujeto a sus propias políticas de privacidad."]],["14. Menores",["OmniDate no recopila conscientemente datos personales de menores ni de otros usuarios."]],["15. Cambios en esta política",["Esta política puede actualizarse a medida que evolucionen las funciones de OmniDate."]],["16. Contacto",["Para cualquier consulta, utiliza la página de soporte de OmniDate."]]]},"support":{"title":"Soporte","intro":"¿Tienes un problema con OmniDate, has encontrado un error o quieres proponer una mejora? Esta página es el punto oficial de soporte de la app.","contact":"Contacto","contactp":"Para solicitar ayuda, escribe a","report":"Informar de un problema","view":"Ver incidencias","before":"Antes de informar de un problema","bullets":["indica el modelo de tu iPhone, iPad o Apple Watch;","indica la versión de iOS, iPadOS o watchOS;","indica la versión de OmniDate;","describe los pasos necesarios para reproducir el problema;","si es un problema de visualización, indica el modelo y la orientación del dispositivo;","si afecta a un eclipse o una lluvia de meteoros, indica la fecha y la ubicación seleccionada;","si afecta a un evento histórico, indica la fecha, el idioma y, si es posible, el título."],"notice":"Por tu seguridad, nunca publiques información personal, contraseñas ni datos confidenciales en una incidencia pública.","faqtitle":"Preguntas frecuentes","faqs":[["¿Qué incluye “Próximos eventos” en OmniDate 1.5.2?","Incluye estaciones, fases de la Luna, perigeos, apogeos, superlunas, eclipses solares y lunares, cambios de hora, lluvias de meteoros, conjunciones y oposiciones planetarias, elongaciones de Mercurio y Venus, perihelio y afelio de la Tierra y pasos de cometas destacados."],["¿Puedo explorar eclipses del pasado?","Sí. OmniDate está diseñada para explorar fechas pasadas y futuras. Los mapas de eclipses permiten estudiar eclipses históricos cuando están disponibles los datos necesarios."],["¿Qué muestran los mapas de eclipses?","Según el tipo de eclipse, pueden mostrar zonas de visibilidad, trayectoria o límites del fenómeno, un punto máximo aproximado y circunstancias calculadas para un lugar seleccionado."],["¿Qué muestra el mapa de una lluvia de meteoros?","Representa las condiciones geométricas de observación según la posición del radiante, la oscuridad del cielo y la influencia de la Luna. Es una ayuda para la observación, no una previsión meteorológica."],["¿Qué incluye “¿Qué ocurrió en esta fecha?”","OmniDate incluye una base local de unos 20.000 eventos históricos. Pueden filtrarse por categoría, abrirse individualmente y recorrerse día a día en la vista completa."],["¿Cómo creo una ficha de fecha en PDF?","Pulsa Compartir y elige “Crear una ficha de fecha”. Introduce fecha, hora y lugar, selecciona los calendarios y previsualiza la ficha antes de guardarla o compartirla."],["¿Para qué usa OmniDate la ubicación?","La ubicación se utiliza para información dependiente del lugar: horarios solares, determinados datos lunares, visibilidad local de eclipses y ciertas condiciones de observación astronómica. Puedes usar tu posición actual, un lugar guardado o una ciudad elegida manualmente."],["¿OmniDate necesita una cuenta?","No. No se necesita ninguna cuenta de usuario."]]},"rtl":false},"it":{"name":"Italiano","nav":{"home":"Home","support":"Supporto","privacy":"Privacy"},"home":{"lead":"Esplora ogni data attraverso calendari, Sole, Luna, storia e astronomia. OmniDate 1.5.2 amplia notevolmente gli eventi astronomici con sciami meteorici, configurazioni planetarie, eventi dell’orbita terrestre, comete notevoli e nuove rappresentazioni delle eclissi passate e future.","pills":["15 lingue","≈ 20.000 eventi storici","Eclissi passate e future","Sciami meteorici","Comete notevoli"],"cards":[["Una data, più calendari","Confronta subito lo stesso giorno nei calendari gregoriano, giuliano, repubblicano francese, cinese, ebraico, islamico, persiano, buddhista, giapponese e ISO 8601."],["Cosa è successo in questa data?","Esplora un database locale di circa 20.000 eventi storici. Filtra per categoria, apri un evento per dettagli e fonti e scorri gli eventi giorno per giorno."],["Prossimi eventi astronomici","Consulta stagioni, fasi lunari, perigei, apogei, superlune, eclissi, cambi d’ora, sciami meteorici, congiunzioni planetarie, opposizioni, elongazioni, perielio, afelio e passaggi di comete notevoli."],["Sciami meteorici","Per i principali sciami meteorici, visualizza su una mappa le condizioni geometriche di osservazione e valuta il potenziale dal luogo selezionato."],["Eclissi nel tempo e nello spazio","Esplora eclissi solari e lunari, future e storiche. Le mappe mostrano le aree di visibilità e, secondo il fenomeno, percorso, limiti e circostanze locali."],["Luna ed eventi lunari","Fase lunare, illuminazione, età della Luna, distanza Terra-Luna, sorgere e tramontare, altezza, azimut e prossimi eventi lunari."],["Segui il percorso del Sole","Alba e tramonto, mezzogiorno solare, durata del giorno, avanzamento del giorno o della notte e crepuscoli civile, nautico e astronomico."],["Effemeridi e astrologia","Consulta onomastici, proverbi e giornate internazionali disponibili, insieme alle informazioni astrologiche offerte da OmniDate."],["Schede data in PDF","Crea una scheda da data, ora e luogo. Riunisci calendari, Sole, Luna, effemeridi e astrologia, quindi salva o condividi il risultato in PDF."],["Date preferite","Salva le date importanti, ritrovale rapidamente e attiva, se vuoi, una notifica annuale."],["Widget personalizzabili","Configura i widget della schermata Home e di blocco per mostrare calendari e informazioni di tuo interesse."],["Apple Watch","Consulta al polso le informazioni essenziali di OmniDate e usa le complicazioni dedicate."]]},"privacy":{"title":"Informativa sulla privacy","updated":"Ultimo aggiornamento: 19 ottobre 2026","notice":"OmniDate 1.5.2 è progettata per funzionare senza account utente, pubblicità, tracciamento tra app o raccolta di dati personali da parte dello sviluppatore.","sections":[["1. Dati raccolti da OmniDate",["OmniDate non richiede un account e non raccoglie, memorizza o trasmette dati personali a un server gestito dallo sviluppatore."]],["2. Dati memorizzati localmente",["Le impostazioni dell’app e le informazioni che scegli di salvare, incluse date preferite, nomi, preferenze di visualizzazione, impostazioni di calendari, effemeridi e notifiche, sono memorizzate localmente sul dispositivo."]],["3. Calcoli calendari e astronomici",["Le conversioni dei calendari e la maggior parte dei calcoli relativi a Sole, Luna, pianeti, eclissi, sciami meteorici, orbita terrestre e altri eventi astronomici vengono eseguiti localmente sul dispositivo. I dati inclusi in OmniDate sono consultati localmente."]],["4. Eventi storici e traduzione",["OmniDate include un database locale di circa 20.000 eventi storici. Consultazione, filtro e navigazione avvengono sul dispositivo. I link Wikipedia/Wikimedia vengono aperti solo quando scegli di consultarli.","Per alcune lingue, OmniDate può utilizzare le funzioni di traduzione di Apple. Lo sviluppatore non riceve testi tradotti né richieste di traduzione."]],["5. Schede data e PDF",["OmniDate può creare una scheda da data, ora, luogo e, se vuoi, un titolo. Queste informazioni sono usate localmente. La condivisione PDF usa le funzioni di iOS o iPadOS e il servizio selezionato."]],["6. Posizione e ricerca luoghi",["Se scegli di usare la posizione attuale, OmniDate accede alla posizione per calcolare informazioni dipendenti dal luogo, inclusi dati solari, alcuni dati lunari, visibilità locale delle eclissi e determinate condizioni di osservazione astronomica.","OmniDate non invia la posizione a un server dello sviluppatore. I servizi di sistema Apple possono essere usati per cercare un luogo o associare una città a coordinate. Puoi anche usare un luogo salvato o una città scelta manualmente."]],["7. Siri e App Intents",["OmniDate può usare Siri e App Intents per alcune informazioni solari. OmniDate non usa un proprio server per elaborare queste richieste."]],["8. Apple Watch",["OmniDate include funzioni e complicazioni per Apple Watch. Lo sviluppatore non raccoglie dati personali aggiuntivi in seguito al loro utilizzo."]],["9. Notifiche",["OmniDate può programmare notifiche locali per alcuni eventi e promemoria annuali per le date preferite. Sono programmati sul dispositivo secondo le tue impostazioni."]],["10. Widget",["I widget della schermata Home e di blocco usano le informazioni necessarie al funzionamento di OmniDate sul dispositivo. Il loro utilizzo non comporta raccolta di dati personali da parte dello sviluppatore."]],["11. Tracciamento, pubblicità e profilazione",["OmniDate non include pubblicità, non effettua tracciamento tra app e non crea profili pubblicitari."]],["12. Servizi Apple",["Apple può trattare alcune informazioni tecniche secondo le proprie politiche e le impostazioni scelte dall’utente. Questo trattamento rientra nei servizi Apple."]],["13. Link esterni",["OmniDate e il suo sito di supporto possono contenere link a Wikipedia, Wikimedia, GitHub o altri servizi esterni. Il loro utilizzo è soggetto alle rispettive informative sulla privacy."]],["14. Minori",["OmniDate non raccoglie consapevolmente dati personali di minori o altri utenti."]],["15. Modifiche a questa informativa",["Questa informativa può essere aggiornata con l’evoluzione delle funzioni di OmniDate."]],["16. Contatti",["Per domande, usa la pagina di supporto OmniDate."]]]},"support":{"title":"Supporto","intro":"Hai un problema con OmniDate, hai trovato un errore o vuoi proporre un miglioramento? Questa è la pagina ufficiale di supporto dell’app.","contact":"Contatti","contactp":"Per assistenza, scrivi a","report":"Segnala un problema","view":"Vedi segnalazioni","before":"Prima di segnalare un problema","bullets":["indica il modello di iPhone, iPad o Apple Watch;","indica la versione di iOS, iPadOS o watchOS;","indica la versione di OmniDate;","descrivi i passaggi necessari per riprodurre il problema;","per problemi di visualizzazione, indica modello e orientamento del dispositivo;","per problemi relativi a eclissi o sciami meteorici, indica data e luogo selezionato;","per un evento storico, indica data, lingua e, se possibile, titolo."],"notice":"Per la tua sicurezza, non pubblicare mai informazioni personali, password o dati riservati in una segnalazione pubblica.","faqtitle":"Domande frequenti","faqs":[["Cosa comprende “Prossimi eventi” in OmniDate 1.5.2?","Stagioni, fasi lunari, perigei, apogei, superlune, eclissi solari e lunari, cambi d’ora, sciami meteorici, congiunzioni e opposizioni planetarie, elongazioni di Mercurio e Venere, perielio e afelio terrestri e passaggi di comete notevoli."],["Posso esplorare le eclissi del passato?","Sì. OmniDate è progettata per esplorare date passate e future. Le mappe possono quindi mostrare eclissi storiche quando i dati necessari sono disponibili."],["Cosa mostrano le mappe delle eclissi?","A seconda del tipo di eclissi, possono mostrare aree di visibilità, percorso o limiti del fenomeno, un punto massimo approssimativo e le circostanze calcolate per un luogo selezionato."],["Cosa mostra la mappa di uno sciame meteorico?","Rappresenta le condizioni geometriche di osservazione in base alla posizione del radiante, all’oscurità del cielo e all’influenza della Luna. È un aiuto all’osservazione, non una previsione meteo."],["Cosa comprende “Cosa è successo in questa data?”","OmniDate include un database locale di circa 20.000 eventi storici. Possono essere filtrati per categoria, aperti singolarmente e consultati giorno per giorno nella vista completa."],["Come creo una scheda data in PDF?","Tocca Condividi e scegli “Crea una scheda data”. Inserisci data, ora e luogo, seleziona i calendari e visualizza l’anteprima prima di salvare o condividere."],["A cosa serve la posizione in OmniDate?","La posizione serve per informazioni dipendenti dal luogo: orari solari, alcuni dati lunari, visibilità locale delle eclissi e determinate condizioni di osservazione astronomica. Puoi usare la posizione attuale, un luogo salvato o una città scelta manualmente."],["OmniDate richiede un account?","No. Non è richiesto alcun account utente."]]},"rtl":false},"pt":{"name":"Português","nav":{"home":"Início","support":"Suporte","privacy":"Privacidade"},"home":{"lead":"Explore cada data através dos calendários, do Sol, da Lua, da história e da astronomia. O OmniDate 1.5.2 amplia bastante os eventos astronómicos com chuvas de meteoros, configurações planetárias, eventos da órbita terrestre, cometas notáveis e novas representações de eclipses passados e futuros.","pills":["15 idiomas","≈ 20 000 eventos históricos","Eclipses passados e futuros","Chuvas de meteoros","Cometas notáveis"],"cards":[["Uma data, vários calendários","Compare imediatamente o mesmo dia nos calendários gregoriano, juliano, republicano francês, chinês, hebraico, islâmico, persa, budista, japonês e ISO 8601."],["O que aconteceu nesta data?","Explore uma base local com cerca de 20 000 eventos históricos. Filtre por categoria, abra um evento para ver detalhes e fontes e percorra os eventos dia a dia."],["Próximos eventos astronómicos","Consulte estações, fases da Lua, perigeus, apogeus, superluas, eclipses, mudanças de hora, chuvas de meteoros, conjunções planetárias, oposições, elongações, periélio, afélio e passagens de cometas notáveis."],["Chuvas de meteoros","Para as principais chuvas de meteoros, visualize num mapa as condições geométricas de observação e avalie o potencial a partir do local selecionado."],["Eclipses no tempo e no espaço","Explore eclipses solares e lunares, futuros e históricos. Os mapas mostram áreas de visibilidade e, consoante o fenómeno, trajetória, limites e circunstâncias locais."],["Lua e eventos lunares","Fase da Lua, iluminação, idade da Lua, distância Terra-Lua, nascer e pôr, altitude, azimute e próximos eventos lunares."],["Siga o percurso do Sol","Nascer e pôr do Sol, meio-dia solar, duração do dia, progressão do dia ou da noite e crepúsculos civil, náutico e astronómico."],["Efemérides e astrologia","Consulte dias de nome, provérbios e dias internacionais disponíveis, juntamente com as informações astrológicas fornecidas pelo OmniDate."],["Fichas de data em PDF","Crie uma ficha a partir de uma data, hora e local. Reúna calendários, Sol, Lua, efemérides e astrologia e guarde ou partilhe o resultado em PDF."],["Datas favoritas","Guarde datas importantes, volte rapidamente a elas e, se desejar, ative uma notificação anual."],["Widgets personalizáveis","Configure widgets do ecrã principal e do ecrã bloqueado para mostrar os calendários e informações que lhe interessam."],["Apple Watch","Consulte no pulso as informações essenciais do OmniDate e use as complicações dedicadas."]]},"privacy":{"title":"Política de Privacidade","updated":"Última atualização: 19 de outubro de 2026","notice":"O OmniDate 1.5.2 foi concebido para funcionar sem conta de utilizador, publicidade, rastreio entre apps ou recolha de dados pessoais pelo programador.","sections":[["1. Dados recolhidos pelo OmniDate",["O OmniDate não exige conta e não recolhe, armazena nem transmite dados pessoais para um servidor operado pelo programador."]],["2. Dados armazenados localmente",["As definições da app e as informações que decide guardar, incluindo datas favoritas, nomes, preferências de apresentação, definições de calendários, efemérides e notificações, ficam armazenadas localmente no dispositivo."]],["3. Cálculos de calendário e astronómicos",["As conversões de calendários e a maioria dos cálculos relativos ao Sol, Lua, planetas, eclipses, chuvas de meteoros, órbita terrestre e outros eventos astronómicos são efetuados localmente no dispositivo. Os dados incluídos no OmniDate são consultados localmente."]],["4. Eventos históricos e tradução",["O OmniDate inclui uma base local com cerca de 20 000 eventos históricos. A consulta, filtragem e navegação são efetuadas no dispositivo. As ligações Wikipedia/Wikimedia só são abertas quando decide consultá-las.","Para alguns idiomas, o OmniDate pode utilizar as funções de tradução da Apple. O programador não recebe textos traduzidos nem pedidos de tradução."]],["5. Fichas de data e PDF",["O OmniDate pode criar uma ficha a partir de uma data, hora, local e, se desejar, um título. Estas informações são utilizadas localmente. A partilha de PDF utiliza as funções do iOS ou iPadOS e o serviço escolhido."]],["6. Localização e pesquisa de locais",["Quando opta por usar a localização atual, o OmniDate acede à localização para calcular informações dependentes do local, incluindo dados solares, alguns dados lunares, visibilidade local de eclipses e certas condições de observação astronómica.","O OmniDate não envia a localização para um servidor do programador. Os serviços Apple podem ser usados para procurar um local ou associar uma cidade a coordenadas. Também pode usar um local guardado ou uma cidade escolhida manualmente."]],["7. Siri e App Intents",["O OmniDate pode utilizar Siri e App Intents para algumas informações solares. O OmniDate não utiliza um servidor próprio para processar estes pedidos."]],["8. Apple Watch",["O OmniDate inclui funções e complicações para Apple Watch. O programador não recolhe dados pessoais adicionais devido à sua utilização."]],["9. Notificações",["O OmniDate pode agendar notificações locais para determinados eventos e lembretes anuais para datas favoritas. São agendadas no dispositivo segundo as suas definições."]],["10. Widgets",["Os widgets do ecrã principal e do ecrã bloqueado utilizam as informações necessárias ao funcionamento do OmniDate no dispositivo. A sua utilização não implica recolha de dados pessoais pelo programador."]],["11. Rastreio, publicidade e criação de perfis",["O OmniDate não inclui publicidade, não efetua rastreio entre apps e não cria perfis publicitários."]],["12. Serviços Apple",["A Apple pode tratar determinadas informações técnicas de acordo com as suas políticas e as definições escolhidas pelo utilizador. Esse tratamento faz parte dos serviços Apple."]],["13. Ligações externas",["O OmniDate e o seu site de suporte podem conter ligações para Wikipedia, Wikimedia, GitHub ou outros serviços externos. A utilização está sujeita às respetivas políticas de privacidade."]],["14. Crianças",["O OmniDate não recolhe conscientemente dados pessoais de crianças ou outros utilizadores."]],["15. Alterações a esta política",["Esta política pode ser atualizada à medida que as funcionalidades do OmniDate evoluem."]],["16. Contacto",["Para questões, utilize a página de suporte do OmniDate."]]]},"support":{"title":"Suporte","intro":"Está com um problema no OmniDate, encontrou um erro ou quer sugerir uma melhoria? Esta página é o ponto oficial de suporte da app.","contact":"Contacto","contactp":"Para pedidos de suporte, escreva para","report":"Comunicar um problema","view":"Ver problemas","before":"Antes de comunicar um problema","bullets":["indique o modelo do iPhone, iPad ou Apple Watch;","indique a versão do iOS, iPadOS ou watchOS;","indique a versão do OmniDate;","descreva os passos necessários para reproduzir o problema;","para um problema de apresentação, indique o modelo e a orientação do dispositivo;","para um problema com eclipse ou chuva de meteoros, indique a data e o local selecionado;","para um evento histórico, indique a data, o idioma e, se possível, o título."],"notice":"Para sua segurança, nunca publique informações pessoais, palavras-passe ou dados confidenciais num pedido público.","faqtitle":"Perguntas frequentes","faqs":[["O que inclui « Próximos eventos » no OmniDate 1.5.2?","Inclui estações, fases da Lua, perigeus, apogeus, superluas, eclipses solares e lunares, mudanças de hora, chuvas de meteoros, conjunções e oposições planetárias, elongações de Mercúrio e Vénus, periélio e afélio da Terra e passagens de cometas notáveis."],["Posso explorar eclipses do passado?","Sim. O OmniDate foi concebido para explorar datas passadas e futuras. Os mapas podem estudar eclipses históricos quando os dados necessários estão disponíveis."],["O que mostram os mapas de eclipses?","Consoante o tipo de eclipse, podem mostrar áreas de visibilidade, trajetória ou limites do fenómeno, um ponto máximo aproximado e circunstâncias calculadas para um local selecionado."],["O que mostra o mapa de uma chuva de meteoros?","Representa condições geométricas de observação segundo a posição do radiante, a escuridão do céu e a influência da Lua. É uma ajuda à observação, não uma previsão meteorológica."],["O que inclui « O que aconteceu nesta data? »","O OmniDate inclui uma base local com cerca de 20 000 eventos históricos. Podem ser filtrados por categoria, abertos individualmente e percorridos dia a dia na vista completa."],["Como criar uma ficha de data em PDF?","Toque em Partilhar e escolha « Criar uma ficha de data ». Introduza a data, hora e local, selecione os calendários e pré-visualize a ficha antes de guardar ou partilhar."],["Para que serve a localização?","A localização é usada para informações dependentes do local: horários solares, alguns dados lunares, visibilidade local dos eclipses e determinadas condições de observação astronómica. Pode usar a posição atual, um local guardado ou uma cidade escolhida manualmente."],["O OmniDate exige uma conta?","Não. Não é necessária qualquer conta de utilizador."]]},"rtl":false},"nl":{"name":"Nederlands","nav":{"home":"Start","support":"Ondersteuning","privacy":"Privacy"},"home":{"lead":"Verken elke datum via kalenders, de zon, de maan, geschiedenis en astronomie. OmniDate 1.5.2 breidt astronomische gebeurtenissen sterk uit met meteorenzwermen, planeetconfiguraties, gebeurtenissen in de aardbaan, opvallende kometen en nieuwe weergaven van vroegere en toekomstige eclipsen.","pills":["15 talen","≈ 20.000 historische gebeurtenissen","Historische en toekomstige eclipsen","Meteorenzwermen","Opvallende kometen"],"cards":[["Eén datum, meerdere kalenders","Vergelijk dezelfde dag direct in de Gregoriaanse, Juliaanse, Franse Republikeinse, Chinese, Hebreeuwse, islamitische, Perzische, boeddhistische en Japanse kalender en volgens ISO 8601."],["Wat gebeurde er op deze datum?","Verken een lokale database met ongeveer 20.000 historische gebeurtenissen. Filter op categorie, open een gebeurtenis voor details en bronnen en blader dag voor dag."],["Komende astronomische gebeurtenissen","Bekijk seizoenen, maanfasen, perigeum, apogeum, supermanen, eclipsen, tijdswijzigingen, meteorenzwermen, planeetconjuncties, opposities, elongaties, perihelium, aphelium en opvallende komeetpassages."],["Meteorenzwermen","Bekijk voor de belangrijkste meteorenzwermen geometrische waarnemingsomstandigheden op een kaart en beoordeel het waarnemingspotentieel vanaf de gekozen locatie."],["Eclipsen door tijd en ruimte","Verken zonne- en maansverduisteringen, zowel toekomstige als historische. Speciale kaarten tonen zichtbaarheidsgebieden en, afhankelijk van het verschijnsel, het pad, de grenzen en lokale omstandigheden."],["Maan en maangebeurtenissen","Maanfase, verlichting, maanleeftijd, afstand aarde-maan, maanopkomst en -ondergang, hoogte, azimut en komende maangebeurtenissen."],["Volg de zon","Zonsopkomst, zonsondergang, zonnemiddag, daglengte, voortgang van dag of nacht en burgerlijke, nautische en astronomische schemering."],["Efemeriden en astrologie","Bekijk beschikbare naamdagen, traditionele spreuken en internationale dagen, samen met de astrologische informatie van OmniDate."],["PDF-datumbladen","Maak een datumblad van een datum, tijd en plaats. Combineer kalenders, zon, maan, efemeriden en astrologie en bewaar of deel het resultaat als PDF."],["Favoriete datums","Bewaar belangrijke datums, open ze snel opnieuw en schakel desgewenst een jaarlijkse melding in."],["Aanpasbare widgets","Configureer widgets op het beginscherm en vergrendelscherm om de kalenders en informatie te tonen die voor jou belangrijk zijn."],["Apple Watch","Bekijk essentiële OmniDate-informatie om je pols en gebruik de speciale complicaties."]]},"privacy":{"title":"Privacybeleid","updated":"Laatst bijgewerkt: 19 oktober 2026","notice":"OmniDate 1.5.2 is ontworpen om te werken zonder gebruikersaccount, advertenties, tracking tussen apps of verzameling van persoonsgegevens door de ontwikkelaar.","sections":[["1. Gegevens verzameld door OmniDate",["OmniDate vereist geen account en verzamelt, bewaart of verzendt geen persoonsgegevens naar een server van de ontwikkelaar."]],["2. Lokaal opgeslagen gegevens",["App-instellingen en informatie die je opslaat, waaronder favoriete datums, namen, weergavevoorkeuren en instellingen voor kalenders, efemeriden en meldingen, worden lokaal op je apparaat bewaard."]],["3. Kalender- en astronomische berekeningen",["Kalenderconversies en de meeste berekeningen voor zon, maan, planeten, eclipsen, meteorenzwermen, aardbaan en andere astronomische gebeurtenissen worden lokaal op het apparaat uitgevoerd. In OmniDate opgenomen gegevens worden lokaal gebruikt."]],["4. Historische gebeurtenissen en vertaling",["OmniDate bevat een lokale database met ongeveer 20.000 historische gebeurtenissen. Bekijken, filteren en navigeren gebeurt op het apparaat. Wikipedia/Wikimedia-links worden alleen geopend wanneer je dat kiest.","Voor sommige talen kan OmniDate de vertaalfuncties van Apple gebruiken. De ontwikkelaar ontvangt geen vertaalde tekst of vertaalverzoeken."]],["5. Datumbladen en PDF",["OmniDate kan een datumblad maken op basis van datum, tijd, plaats en eventueel een titel. Deze informatie wordt lokaal gebruikt. PDF-delen gebruikt de deelfuncties van iOS of iPadOS en de gekozen dienst."]],["6. Locatie en zoeken naar plaatsen",["Wanneer je je huidige locatie gebruikt, heeft OmniDate toegang tot de locatie om plaatsafhankelijke informatie te berekenen, waaronder zonnegegevens, bepaalde maangegevens, lokale zichtbaarheid van eclipsen en bepaalde astronomische waarnemingsomstandigheden.","OmniDate stuurt je locatie niet naar een server van de ontwikkelaar. Apple-systeemdiensten kunnen worden gebruikt om een plaats te zoeken of een stadsnaam aan coördinaten te koppelen. Je kunt ook een opgeslagen plaats of handmatig gekozen stad gebruiken."]],["7. Siri en App Intents",["OmniDate kan Siri en App Intents gebruiken voor bepaalde zonne-informatie. OmniDate gebruikt geen eigen server om deze verzoeken te verwerken."]],["8. Apple Watch",["OmniDate bevat Apple Watch-functies en complicaties. De ontwikkelaar verzamelt hierdoor geen aanvullende persoonsgegevens."]],["9. Meldingen",["OmniDate kan lokale meldingen voor bepaalde gebeurtenissen en jaarlijkse herinneringen voor favoriete datums plannen. Ze worden volgens je instellingen op het apparaat gepland."]],["10. Widgets",["Widgets op het beginscherm en vergrendelscherm gebruiken de informatie die nodig is om OmniDate op het apparaat te laten werken. Het gebruik ervan leidt niet tot verzameling van persoonsgegevens door de ontwikkelaar."]],["11. Tracking, advertenties en profilering",["OmniDate bevat geen advertenties, voert geen tracking tussen apps uit en maakt geen advertentieprofielen."]],["12. Apple-diensten",["Apple kan bepaalde technische informatie verwerken volgens zijn eigen beleid en de door de gebruiker gekozen instellingen. Deze verwerking hoort bij Apple-diensten."]],["13. Externe links",["OmniDate en de ondersteuningssite kunnen links bevatten naar Wikipedia, Wikimedia, GitHub of andere externe diensten. Het gebruik daarvan valt onder hun eigen privacybeleid."]],["14. Kinderen",["OmniDate verzamelt niet bewust persoonsgegevens van kinderen of andere gebruikers."]],["15. Wijzigingen in dit beleid",["Dit beleid kan worden bijgewerkt wanneer de functies van OmniDate veranderen."]],["16. Contact",["Gebruik voor vragen de OmniDate-ondersteuningspagina."]]]},"support":{"title":"Ondersteuning","intro":"Heb je een probleem met OmniDate, een fout gevonden of een verbetersuggestie? Deze pagina is het officiële ondersteuningspunt voor de app.","contact":"Contact","contactp":"Voor ondersteuning kun je mailen naar","report":"Probleem melden","view":"Meldingen bekijken","before":"Voordat je een probleem meldt","bullets":["vermeld je iPhone-, iPad- of Apple Watch-model;","vermeld je iOS-, iPadOS- of watchOS-versie;","vermeld je OmniDate-versie;","beschrijf de stappen om het probleem te reproduceren;","vermeld bij een weergaveprobleem het apparaatmodel en de oriëntatie;","vermeld bij een eclips- of meteorenzwermprobleem de datum en gekozen locatie;","vermeld bij een historische gebeurtenis de datum, taal en indien mogelijk de titel."],"notice":"Plaats voor je veiligheid nooit persoonlijke gegevens, wachtwoorden of vertrouwelijke informatie in een openbaar ticket.","faqtitle":"Veelgestelde vragen","faqs":[["Wat bevat ‘Komende gebeurtenissen’ in OmniDate 1.5.2?","Seizoenen, maanfasen, perigeum, apogeum, supermanen, zonne- en maansverduisteringen, tijdswijzigingen, meteorenzwermen, planeetconjuncties en -opposities, elongaties van Mercurius en Venus, perihelium en aphelium van de aarde en opvallende komeetpassages."],["Kan ik eclipsen uit het verleden verkennen?","Ja. OmniDate is gemaakt voor zowel vroegere als toekomstige datums. Eclipskaarten kunnen historische eclipsen tonen wanneer de nodige gegevens beschikbaar zijn."],["Wat tonen eclipskaarten?","Afhankelijk van het type eclips kunnen ze zichtbaarheidsgebieden, baan of grenzen, een benaderd maximumpunt en berekende omstandigheden voor een gekozen locatie tonen."],["Wat toont een kaart van een meteorenzwerm?","De kaart toont geometrische waarnemingsomstandigheden op basis van radiantpositie, hemelduisternis en invloed van de maan. Het is een observatiehulpmiddel, geen weersverwachting."],["Wat bevat ‘Wat gebeurde er op deze datum?’","OmniDate bevat een lokale database met ongeveer 20.000 historische gebeurtenissen. Ze kunnen per categorie worden gefilterd, afzonderlijk geopend en dag voor dag worden bekeken."],["Hoe maak ik een PDF-datumblad?","Tik op Delen en kies ‘Een datumblad maken’. Voer datum, tijd en plaats in, selecteer kalenders en bekijk het voorbeeld voordat je opslaat of deelt."],["Waarom gebruikt OmniDate locatie?","Locatie wordt gebruikt voor plaatsafhankelijke informatie: zonnetijden, bepaalde maangegevens, lokale zichtbaarheid van eclipsen en bepaalde astronomische waarnemingsomstandigheden. Je kunt je huidige locatie, een opgeslagen plaats of een handmatig gekozen stad gebruiken."],["Heeft OmniDate een account nodig?","Nee. Er is geen gebruikersaccount nodig."]]},"rtl":false},"pl":{"name":"Polski","nav":{"home":"Strona główna","support":"Pomoc","privacy":"Prywatność"},"home":{"lead":"Poznawaj każdą datę przez kalendarze, Słońce, Księżyc, historię i astronomię. OmniDate 1.5.2 znacznie rozszerza wydarzenia astronomiczne o roje meteorów, konfiguracje planet, zdarzenia związane z orbitą Ziemi, wyjątkowe komety oraz nowe wizualizacje dawnych i przyszłych zaćmień.","pills":["15 języków","≈ 20 000 wydarzeń historycznych","Zaćmienia przeszłe i przyszłe","Roje meteorów","Wyjątkowe komety"],"cards":[["Jedna data, wiele kalendarzy","Porównuj ten sam dzień w kalendarzu gregoriańskim, juliańskim, francuskim republikańskim, chińskim, hebrajskim, islamskim, perskim, buddyjskim, japońskim oraz ISO 8601."],["Co wydarzyło się tego dnia?","Przeglądaj lokalną bazę około 20 000 wydarzeń historycznych. Filtruj według kategorii, otwieraj wydarzenia z detalami i źródłami oraz przechodź dzień po dniu."],["Nadchodzące wydarzenia astronomiczne","Pory roku, fazy Księżyca, perygeum, apogeum, superksiężyce, zaćmienia, zmiany czasu, roje meteorów, koniunkcje planet, opozycje, elongacje, peryhelium, aphelium i przejścia wyjątkowych komet."],["Roje meteorów","Dla głównych rojów meteorów zobacz na mapie geometryczne warunki obserwacji i oceń potencjał z wybranego miejsca."],["Zaćmienia w czasie i przestrzeni","Poznawaj zaćmienia Słońca i Księżyca, przyszłe i historyczne. Mapy pokazują obszary widoczności oraz, zależnie od zjawiska, przebieg, granice i warunki lokalne."],["Księżyc i wydarzenia księżycowe","Faza Księżyca, oświetlenie, wiek Księżyca, odległość Ziemia-Księżyc, wschód i zachód, wysokość, azymut i kolejne wydarzenia księżycowe."],["Śledź drogę Słońca","Wschód i zachód Słońca, południe słoneczne, długość dnia, postęp dnia lub nocy oraz zmierzch cywilny, żeglarski i astronomiczny."],["Efemerydy i astrologia","Sprawdzaj imieniny, przysłowia i dni międzynarodowe oraz informacje astrologiczne oferowane przez OmniDate."],["Karty daty PDF","Utwórz kartę z daty, godziny i miejsca. Połącz kalendarze, Słońce, Księżyc, efemerydy i astrologię, a następnie zapisz lub udostępnij wynik jako PDF."],["Ulubione daty","Zapisuj ważne daty, szybko do nich wracaj i opcjonalnie włącz roczne powiadomienie."],["Konfigurowalne widżety","Skonfiguruj widżety ekranu początkowego i blokady, aby pokazywały wybrane kalendarze i informacje."],["Apple Watch","Sprawdzaj najważniejsze informacje OmniDate na nadgarstku i korzystaj z dedykowanych komplikacji."]]},"privacy":{"title":"Polityka prywatności","updated":"Ostatnia aktualizacja: 19 października 2026","notice":"OmniDate 1.5.2 działa bez konta użytkownika, reklam, śledzenia między aplikacjami i gromadzenia danych osobowych przez twórcę.","sections":[["1. Dane gromadzone przez OmniDate",["OmniDate nie wymaga konta i nie gromadzi, nie przechowuje ani nie przesyła danych osobowych na serwer obsługiwany przez twórcę."]],["2. Dane przechowywane lokalnie",["Ustawienia aplikacji i zapisane informacje, w tym ulubione daty, nazwy, preferencje wyświetlania oraz ustawienia kalendarzy, efemeryd i powiadomień, są przechowywane lokalnie na urządzeniu."]],["3. Obliczenia kalendarzowe i astronomiczne",["Konwersje kalendarzy oraz większość obliczeń dotyczących Słońca, Księżyca, planet, zaćmień, rojów meteorów, orbity Ziemi i innych wydarzeń astronomicznych wykonywana jest lokalnie na urządzeniu. Dane dołączone do OmniDate są używane lokalnie."]],["4. Wydarzenia historyczne i tłumaczenie",["OmniDate zawiera lokalną bazę około 20 000 wydarzeń historycznych. Przeglądanie, filtrowanie i nawigacja odbywają się na urządzeniu. Linki Wikipedia/Wikimedia są otwierane tylko na życzenie użytkownika.","Dla niektórych języków OmniDate może korzystać z funkcji tłumaczenia Apple. Twórca nie otrzymuje przetłumaczonych tekstów ani żądań tłumaczenia."]],["5. Karty daty i PDF",["OmniDate może utworzyć kartę na podstawie daty, godziny, miejsca i opcjonalnego tytułu. Informacje te są używane lokalnie. Udostępnianie PDF wykorzystuje funkcje iOS lub iPadOS oraz wybraną usługę."]],["6. Lokalizacja i wyszukiwanie miejsc",["Gdy używasz bieżącej lokalizacji, OmniDate korzysta z niej do obliczania informacji zależnych od miejsca, w tym danych słonecznych, wybranych danych księżycowych, lokalnej widoczności zaćmień i określonych warunków obserwacji astronomicznych.","OmniDate nie wysyła lokalizacji na serwer twórcy. Usługi systemowe Apple mogą służyć do wyszukiwania miejsca lub przypisania nazwy miasta do współrzędnych. Możesz też użyć zapisanego miejsca lub ręcznie wybranego miasta."]],["7. Siri i App Intents",["OmniDate może używać Siri i App Intents do wybranych informacji słonecznych. OmniDate nie używa własnego serwera do przetwarzania tych żądań."]],["8. Apple Watch",["OmniDate oferuje funkcje i komplikacje Apple Watch. Twórca nie gromadzi dodatkowych danych osobowych w wyniku ich używania."]],["9. Powiadomienia",["OmniDate może planować lokalne powiadomienia dla wybranych wydarzeń i coroczne przypomnienia o ulubionych datach. Są planowane na urządzeniu zgodnie z ustawieniami."]],["10. Widżety",["Widżety ekranu początkowego i blokady korzystają z informacji potrzebnych do działania OmniDate na urządzeniu. Ich używanie nie powoduje gromadzenia danych osobowych przez twórcę."]],["11. Śledzenie, reklamy i profilowanie",["OmniDate nie zawiera reklam, nie śledzi użytkownika między aplikacjami i nie tworzy profili reklamowych."]],["12. Usługi Apple",["Apple może przetwarzać określone informacje techniczne zgodnie z własnymi zasadami i ustawieniami wybranymi przez użytkownika. Takie przetwarzanie jest częścią usług Apple."]],["13. Linki zewnętrzne",["OmniDate i jego witryna pomocy mogą zawierać linki do Wikipedia, Wikimedia, GitHub lub innych usług zewnętrznych. Korzystanie z nich podlega ich własnym zasadom prywatności."]],["14. Dzieci",["OmniDate nie gromadzi świadomie danych osobowych dzieci ani innych użytkowników."]],["15. Zmiany w tej polityce",["Polityka może być aktualizowana wraz z rozwojem funkcji OmniDate."]],["16. Kontakt",["W razie pytań skorzystaj ze strony pomocy OmniDate."]]]},"support":{"title":"Pomoc","intro":"Masz problem z OmniDate, znalazłeś błąd lub chcesz zaproponować ulepszenie? To oficjalna strona pomocy aplikacji.","contact":"Kontakt","contactp":"W sprawie pomocy napisz na","report":"Zgłoś problem","view":"Zobacz zgłoszenia","before":"Przed zgłoszeniem problemu","bullets":["podaj model iPhone’a, iPada lub Apple Watch;","podaj wersję iOS, iPadOS lub watchOS;","podaj wersję OmniDate;","opisz kroki potrzebne do odtworzenia problemu;","w przypadku problemu z wyświetlaniem podaj model urządzenia i orientację;","w przypadku problemu z zaćmieniem lub rojem meteorów podaj datę i wybraną lokalizację;","w przypadku wydarzenia historycznego podaj datę, język i, jeśli to możliwe, tytuł."],"notice":"Dla bezpieczeństwa nigdy nie publikuj danych osobowych, haseł ani poufnych informacji w publicznym zgłoszeniu.","faqtitle":"Najczęstsze pytania","faqs":[["Co zawiera sekcja „Nadchodzące wydarzenia” w OmniDate 1.5.2?","Pory roku, fazy Księżyca, perygeum, apogeum, superksiężyce, zaćmienia Słońca i Księżyca, zmiany czasu, roje meteorów, koniunkcje i opozycje planet, elongacje Merkurego i Wenus, peryhelium i aphelium Ziemi oraz przejścia wyjątkowych komet."],["Czy mogę poznawać zaćmienia z przeszłości?","Tak. OmniDate służy do eksplorowania dat przeszłych i przyszłych. Mapy zaćmień mogą więc pokazywać historyczne zaćmienia, gdy dostępne są potrzebne dane."],["Co pokazują mapy zaćmień?","W zależności od typu zaćmienia mogą pokazywać obszary widoczności, przebieg lub granice zjawiska, przybliżony punkt maksimum oraz obliczone okoliczności dla wybranego miejsca."],["Co pokazuje mapa roju meteorów?","Przedstawia geometryczne warunki obserwacji na podstawie położenia radiantu, ciemności nieba i wpływu Księżyca. To pomoc obserwacyjna, a nie prognoza pogody."],["Co zawiera „Co wydarzyło się tego dnia?”","OmniDate zawiera lokalną bazę około 20 000 wydarzeń historycznych. Można je filtrować według kategorii, otwierać pojedynczo i przeglądać dzień po dniu."],["Jak utworzyć kartę daty PDF?","Stuknij Udostępnij i wybierz „Utwórz kartę daty”. Wprowadź datę, godzinę i miejsce, wybierz kalendarze, a następnie wyświetl podgląd przed zapisaniem lub udostępnieniem."],["Do czego OmniDate używa lokalizacji?","Lokalizacja służy do informacji zależnych od miejsca: czasów słonecznych, wybranych danych księżycowych, lokalnej widoczności zaćmień i określonych warunków obserwacji astronomicznych. Możesz użyć bieżącej pozycji, zapisanego miejsca lub ręcznie wybranego miasta."],["Czy OmniDate wymaga konta?","Nie. Konto użytkownika nie jest wymagane."]]},"rtl":false},"zh-Hans":{"name":"简体中文","nav":{"home":"首页","support":"支持","privacy":"隐私"},"home":{"lead":"通过日历、太阳、月亮、历史和天文学探索每一个日期。OmniDate 1.5.2 大幅扩展天文事件，加入流星雨、行星配置、地球轨道事件、著名彗星，以及过去和未来日月食的新视觉呈现。","pills":["15 种语言","≈ 20,000 个历史事件","过去与未来的日月食","流星雨","著名彗星"],"cards":[["一个日期，多种历法","即时比较同一天在公历、儒略历、法国共和历、中国历、希伯来历、伊斯兰历、波斯历、佛历、日本历和 ISO 8601 中的日期。"],["这一天发生了什么？","浏览约 20,000 个历史事件的本地数据库。按类别筛选，打开单个事件查看详情和来源，并逐日浏览。"],["即将发生的天文事件","查看季节、月相、近地点、远地点、超级月亮、日月食、时间调整、流星雨、行星合相、冲、最大距角、近日点、远日点和著名彗星的经过。"],["流星雨","对于主要流星雨，可在地图上查看几何观测条件，并评估所选地点的观测潜力。"],["时空中的日月食","探索未来和历史上的日食与月食。专用地图显示可见区域，并根据事件显示路径、边界和当地情况。"],["月亮与月球事件","月相、照明、月龄、地月距离、月出月落、高度角、方位角和即将发生的月球事件。"],["追踪太阳","日出、日落、太阳正午、昼长、白天或夜晚进度，以及民用、航海和天文曙暮光。"],["星历与占星","查看可用的圣人日、传统谚语和国际纪念日，以及 OmniDate 提供的占星信息。"],["PDF 日期卡片","根据日期、时间和地点创建日期卡片。汇总日历、太阳、月亮、星历和占星信息，然后保存或分享为 PDF。"],["收藏日期","保存重要日期，快速返回查看，并可选择启用年度通知。"],["可自定义小组件","配置主屏幕和锁定屏幕小组件，显示您关心的日历和信息。"],["Apple Watch","在手腕上查看 OmniDate 的核心信息，并使用专用复杂功能。"]]},"privacy":{"title":"隐私政策","updated":"最后更新：2026年10月19日","notice":"OmniDate 1.5.2 无需用户账户，不含广告，不进行跨应用跟踪，开发者也不会收集个人数据。","sections":[["1. OmniDate 收集的数据",["OmniDate 不要求创建账户，也不会收集、存储或向开发者运营的服务器传输个人数据。"]],["2. 本地存储的数据",["应用设置以及您选择保存的信息，包括收藏日期、名称、显示偏好、日历、星历和通知设置，均存储在您的设备本地。"]],["3. 日历与天文计算",["日历转换以及与太阳、月亮、行星、日月食、流星雨、地球轨道和其他天文事件相关的大多数计算都在设备本地完成。OmniDate 内置的数据也在本地使用。"]],["4. 历史事件与翻译",["OmniDate 包含约 20,000 个历史事件的本地数据库。浏览、筛选和导航均在设备上完成。只有在您主动选择时才会打开 Wikipedia/Wikimedia 链接。","对于部分语言，OmniDate 可能使用 Apple 的翻译功能。开发者不会收到翻译后的文本或翻译请求。"]],["5. 日期卡片与 PDF",["OmniDate 可根据日期、时间、地点以及可选标题创建日期卡片。这些信息在本地使用。分享 PDF 时使用 iOS 或 iPadOS 的分享功能以及您选择的服务。"]],["6. 定位与地点搜索",["当您选择使用当前位置时，OmniDate 会访问设备定位，以计算与地点有关的信息，包括太阳数据、部分月球数据、本地日月食可见性和某些天文观测条件。","OmniDate 不会将您的位置发送到开发者运营的服务器。Apple 系统服务可能用于搜索地点或将城市名称与坐标关联。您也可以使用已保存地点或手动选择城市。"]],["7. Siri 与 App Intents",["OmniDate 可使用 Siri 和 App Intents 提供部分太阳信息。OmniDate 不使用自有服务器处理这些请求。"]],["8. Apple Watch",["OmniDate 提供 Apple Watch 功能和复杂功能。开发者不会因使用这些功能而收集额外个人数据。"]],["9. 通知",["OmniDate 可为部分事件安排本地通知，并为收藏日期安排年度提醒。这些通知根据您的设置在设备上安排。"]],["10. 小组件",["主屏幕和锁定屏幕小组件使用 OmniDate 在设备上运行所需的信息。使用这些小组件不会导致开发者收集个人数据。"]],["11. 跟踪、广告与画像",["OmniDate 不包含广告，不进行跨应用跟踪，也不会创建广告画像。"]],["12. Apple 服务",["Apple 可能依据其自身政策及用户选择的设置处理某些技术信息。此类处理属于 Apple 服务。"]],["13. 外部链接",["OmniDate 及其支持网站可能包含指向 Wikipedia、Wikimedia、GitHub 或其他外部服务的链接。使用这些服务时适用其各自的隐私政策。"]],["14. 儿童",["OmniDate 不会主动收集儿童或其他用户的个人数据。"]],["15. 本政策的变更",["随着 OmniDate 功能的发展，本政策可能会更新。"]],["16. 联系",["如有问题，请使用 OmniDate 支持页面。"]]]},"support":{"title":"支持","intro":"如果您在使用 OmniDate 时遇到问题、发现错误或希望提出改进建议，本页面是应用的官方支持入口。","contact":"联系","contactp":"如需支持，请发送邮件至","report":"报告问题","view":"查看问题","before":"报告问题之前","bullets":["请注明您的 iPhone、iPad 或 Apple Watch 型号；","请注明 iOS、iPadOS 或 watchOS 版本；","请注明 OmniDate 版本；","请描述重现问题所需的步骤；","如为显示问题，请注明设备型号和方向；","如涉及日月食或流星雨，请注明日期和所选地点；","如涉及历史事件，请注明日期、所选语言，并尽可能提供事件标题。"],"notice":"为了您的安全，请勿在公开问题中发布个人信息、密码或机密数据。","faqtitle":"常见问题","faqs":[["OmniDate 1.5.2 的“即将发生的事件”包含什么？","包括季节、月相、近地点、远地点、超级月亮、日食和月食、时间调整、流星雨、行星合相和冲、水星与金星的最大距角、地球近日点和远日点，以及著名彗星的经过。"],["可以探索过去的日月食吗？","可以。OmniDate 用于探索过去和未来的日期。因此，在具备所需数据时，日月食地图也可用于研究历史日月食。"],["日月食地图显示什么？","根据日月食类型，地图可显示可见区域、路径或边界、近似最大点，以及所选地点的计算情况。"],["流星雨地图显示什么？","它根据辐射点位置、天空黑暗程度和月亮影响展示几何观测条件。这是一种观测辅助工具，并非天气预报。"],["“这一天发生了什么？”包含什么？","OmniDate 包含约 20,000 个历史事件的本地数据库。可按类别筛选，单独打开，并在完整列表中逐日浏览。"],["如何创建 PDF 日期卡片？","点击“分享”，选择“创建日期卡片”。输入日期、时间和地点，选择日历，然后预览卡片再保存或分享。"],["OmniDate 为什么使用定位？","定位用于与地点有关的信息，包括太阳时间、部分月球信息、本地日月食可见性和某些天文观测条件。您可以使用当前位置、已保存地点或手动选择的城市。"],["OmniDate 需要账户吗？","不需要。无需用户账户。"]]},"rtl":false},"zh-Hant":{"name":"繁體中文","nav":{"home":"首頁","support":"支援","privacy":"隱私"},"home":{"lead":"透過日曆、太陽、月亮、歷史與天文探索每一個日期。OmniDate 1.5.2 大幅擴充天文事件，加入流星雨、行星配置、地球軌道事件、著名彗星，以及過去與未來日月食的新視覺呈現。","pills":["15 種語言","≈ 20,000 個歷史事件","過去與未來的日月食","流星雨","著名彗星"],"cards":[["一個日期，多種曆法","即時比較同一天在公曆、儒略曆、法國共和曆、中國曆、希伯來曆、伊斯蘭曆、波斯曆、佛曆、日本曆與 ISO 8601 中的日期。"],["這一天發生了什麼？","瀏覽約 20,000 個歷史事件的本地資料庫。依類別篩選，開啟單一事件查看詳情與來源，並逐日瀏覽。"],["即將發生的天文事件","查看季節、月相、近地點、遠地點、超級月亮、日月食、時間調整、流星雨、行星合相、衝、最大距角、近日點、遠日點與著名彗星的經過。"],["流星雨","對於主要流星雨，可在地圖上查看幾何觀測條件，並評估所選地點的觀測潛力。"],["時空中的日月食","探索未來與歷史上的日食與月食。專用地圖顯示可見區域，並依事件顯示路徑、邊界與當地情況。"],["月亮與月球事件","月相、照明、月齡、地月距離、月出月落、高度角、方位角與即將發生的月球事件。"],["追蹤太陽","日出、日落、太陽正午、晝長、白天或夜晚進度，以及民用、航海與天文曙暮光。"],["星曆與占星","查看可用的聖人日、傳統諺語與國際紀念日，以及 OmniDate 提供的占星資訊。"],["PDF 日期卡片","根據日期、時間與地點建立日期卡片。整合日曆、太陽、月亮、星曆與占星資訊，然後儲存或分享為 PDF。"],["收藏日期","儲存重要日期，快速返回查看，並可選擇啟用年度通知。"],["可自訂小工具","設定主畫面與鎖定畫面小工具，顯示您關心的日曆與資訊。"],["Apple Watch","在手腕上查看 OmniDate 的核心資訊，並使用專用複雜功能。"]]},"privacy":{"title":"隱私權政策","updated":"最後更新：2026年10月19日","notice":"OmniDate 1.5.2 無需使用者帳戶，不含廣告，不進行跨應用程式追蹤，開發者也不會收集個人資料。","sections":[["1. OmniDate 收集的資料",["OmniDate 不要求建立帳戶，也不會收集、儲存或向開發者營運的伺服器傳輸個人資料。"]],["2. 本地儲存的資料",["應用程式設定以及您選擇儲存的資訊，包括收藏日期、名稱、顯示偏好、日曆、星曆與通知設定，均儲存在您的裝置本地。"]],["3. 日曆與天文計算",["日曆轉換以及與太陽、月亮、行星、日月食、流星雨、地球軌道與其他天文事件相關的大多數計算都在裝置本地完成。OmniDate 內建的資料也在本地使用。"]],["4. 歷史事件與翻譯",["OmniDate 包含約 20,000 個歷史事件的本地資料庫。瀏覽、篩選與導覽均在裝置上完成。只有在您主動選擇時才會開啟 Wikipedia/Wikimedia 連結。","對於部分語言，OmniDate 可能使用 Apple 的翻譯功能。開發者不會收到翻譯後的文字或翻譯要求。"]],["5. 日期卡片與 PDF",["OmniDate 可根據日期、時間、地點以及可選標題建立日期卡片。這些資訊在本地使用。分享 PDF 時使用 iOS 或 iPadOS 的分享功能與您選擇的服務。"]],["6. 定位與地點搜尋",["當您選擇使用目前位置時，OmniDate 會存取裝置定位，以計算與地點有關的資訊，包括太陽資料、部分月球資料、本地日月食可見性與某些天文觀測條件。","OmniDate 不會將您的位置傳送到開發者營運的伺服器。Apple 系統服務可能用於搜尋地點或將城市名稱與座標關聯。您也可以使用已儲存地點或手動選擇城市。"]],["7. Siri 與 App Intents",["OmniDate 可使用 Siri 與 App Intents 提供部分太陽資訊。OmniDate 不使用自有伺服器處理這些要求。"]],["8. Apple Watch",["OmniDate 提供 Apple Watch 功能與複雜功能。開發者不會因使用這些功能而收集額外個人資料。"]],["9. 通知",["OmniDate 可為部分事件安排本地通知，並為收藏日期安排年度提醒。這些通知依您的設定在裝置上安排。"]],["10. 小工具",["主畫面與鎖定畫面小工具使用 OmniDate 在裝置上運作所需的資訊。使用這些小工具不會導致開發者收集個人資料。"]],["11. 追蹤、廣告與個人化分析",["OmniDate 不包含廣告，不進行跨應用程式追蹤，也不會建立廣告個人檔案。"]],["12. Apple 服務",["Apple 可能依據其自身政策與使用者選擇的設定處理某些技術資訊。此類處理屬於 Apple 服務。"]],["13. 外部連結",["OmniDate 及其支援網站可能包含指向 Wikipedia、Wikimedia、GitHub 或其他外部服務的連結。使用這些服務時適用其各自的隱私權政策。"]],["14. 兒童",["OmniDate 不會主動收集兒童或其他使用者的個人資料。"]],["15. 本政策的變更",["隨著 OmniDate 功能發展，本政策可能會更新。"]],["16. 聯絡",["如有問題，請使用 OmniDate 支援頁面。"]]]},"support":{"title":"支援","intro":"如果您在使用 OmniDate 時遇到問題、發現錯誤或希望提出改進建議，本頁面是應用程式的官方支援入口。","contact":"聯絡","contactp":"如需支援，請寄送電子郵件至","report":"回報問題","view":"查看問題","before":"回報問題之前","bullets":["請註明您的 iPhone、iPad 或 Apple Watch 型號；","請註明 iOS、iPadOS 或 watchOS 版本；","請註明 OmniDate 版本；","請描述重現問題所需的步驟；","如為顯示問題，請註明裝置型號與方向；","如涉及日月食或流星雨，請註明日期與所選地點；","如涉及歷史事件，請註明日期、所選語言，並盡可能提供事件標題。"],"notice":"為了您的安全，請勿在公開問題中發布個人資訊、密碼或機密資料。","faqtitle":"常見問題","faqs":[["OmniDate 1.5.2 的「即將發生的事件」包含什麼？","包括季節、月相、近地點、遠地點、超級月亮、日食與月食、時間調整、流星雨、行星合相與衝、水星與金星的最大距角、地球近日點與遠日點，以及著名彗星的經過。"],["可以探索過去的日月食嗎？","可以。OmniDate 用於探索過去與未來的日期。因此，在具備所需資料時，日月食地圖也可用於研究歷史日月食。"],["日月食地圖顯示什麼？","依日月食類型，地圖可顯示可見區域、路徑或邊界、近似最大點，以及所選地點的計算情況。"],["流星雨地圖顯示什麼？","它依輻射點位置、天空黑暗程度與月亮影響展示幾何觀測條件。這是一種觀測輔助工具，並非天氣預報。"],["「這一天發生了什麼？」包含什麼？","OmniDate 包含約 20,000 個歷史事件的本地資料庫。可依類別篩選、單獨開啟，並在完整清單中逐日瀏覽。"],["如何建立 PDF 日期卡片？","點選「分享」，選擇「建立日期卡片」。輸入日期、時間與地點，選擇日曆，然後預覽卡片再儲存或分享。"],["OmniDate 為什麼使用定位？","定位用於與地點有關的資訊，包括太陽時間、部分月球資訊、本地日月食可見性與某些天文觀測條件。您可以使用目前位置、已儲存地點或手動選擇的城市。"],["OmniDate 需要帳戶嗎？","不需要。無需使用者帳戶。"]]},"rtl":false},"ja":{"name":"日本語","nav":{"home":"ホーム","support":"サポート","privacy":"プライバシー"},"home":{"lead":"暦、太陽、月、歴史、天文学を通してあらゆる日付を探索できます。OmniDate 1.5.2では、流星群、惑星配置、地球軌道イベント、注目の彗星、過去と未来の日食・月食の新しい表示を追加し、天文イベントを大幅に拡充しました。","pills":["15言語","約20,000件の歴史イベント","過去と未来の日食・月食","流星群","注目の彗星"],"cards":[["1つの日付、複数の暦","同じ日をグレゴリオ暦、ユリウス暦、フランス革命暦、中国暦、ヘブライ暦、イスラム暦、ペルシャ暦、仏暦、日本暦、ISO 8601で即座に比較できます。"],["この日に何が起きた？","約20,000件の歴史イベントを収録したローカルデータベースを探索できます。カテゴリで絞り込み、詳細と出典を開き、日ごとに移動できます。"],["今後の天文イベント","季節、月相、近地点、遠地点、スーパームーン、日食・月食、時刻変更、流星群、惑星の合と衝、離角、近日点、遠日点、注目の彗星の通過を確認できます。"],["流星群","主要な流星群について、地図上で幾何学的な観測条件を表示し、選択した場所からの観測可能性を確認できます。"],["時間と空間で見る日食・月食","未来と過去の日食・月食を探索できます。専用地図では可視範囲と、現象に応じて経路、境界、地域ごとの状況を表示します。"],["月と月のイベント","月相、照明率、月齢、地球と月の距離、月の出と月の入り、高度、方位角、今後の月イベント。"],["太陽の動きを追う","日の出、日の入り、南中時刻、昼の長さ、昼夜の進行、常用・航海・天文薄明を確認できます。"],["暦注と占星術","利用可能な聖人暦、ことわざ、国際デーと、OmniDateが提供する占星術情報を確認できます。"],["PDF日付シート","日付、時刻、場所からシートを作成し、暦、太陽、月、暦注、占星術をまとめてPDFで保存または共有できます。"],["お気に入りの日付","大切な日付を保存してすばやく呼び出し、必要に応じて年次通知を有効にできます。"],["カスタマイズ可能なウィジェット","ホーム画面とロック画面のウィジェットを設定し、必要な暦や情報を表示できます。"],["Apple Watch","OmniDateの重要な情報を手首で確認し、専用コンプリケーションを利用できます。"]]},"privacy":{"title":"プライバシーポリシー","updated":"最終更新：2026年10月19日","notice":"OmniDate 1.5.2は、ユーザーアカウント、広告、アプリ間トラッキング、開発者による個人データ収集なしで動作するよう設計されています。","sections":[["1. OmniDateが収集するデータ",["OmniDateはアカウントを必要とせず、開発者が運営するサーバーへ個人データを収集、保存、送信しません。"]],["2. 端末内に保存されるデータ",["お気に入りの日付、その名称、表示設定、暦、暦注、通知設定など、アプリの設定と保存を選択した情報は端末内に保存されます。"]],["3. 暦と天文計算",["暦の変換、太陽、月、惑星、日食・月食、流星群、地球軌道などの天文計算の大部分は端末内で行われます。OmniDateに含まれるデータも端末内で使用されます。"]],["4. 歴史イベントと翻訳",["OmniDateには約20,000件の歴史イベントを収録したローカルデータベースがあります。閲覧、絞り込み、移動は端末内で行われます。Wikipedia/Wikimediaのリンクはユーザーが選択した場合のみ開きます。","一部の言語ではAppleの翻訳機能を利用する場合があります。開発者は翻訳された文章や翻訳リクエストを受け取りません。"]],["5. 日付シートとPDF",["OmniDateは日付、時刻、場所、任意のタイトルから日付シートを作成できます。これらの情報は端末内で使用されます。PDF共有にはiOSまたはiPadOSの共有機能と選択したサービスが使われます。"]],["6. 位置情報と場所検索",["現在地を使用すると、OmniDateは位置情報にアクセスし、太陽データ、一部の月データ、日食・月食の地域別可視性、特定の天文観測条件など、場所に依存する情報を計算します。","OmniDateは位置情報を開発者のサーバーへ送信しません。場所検索や座標への都市名の関連付けにAppleのシステムサービスが使われる場合があります。保存済みの場所や手動で選択した都市も利用できます。"]],["7. SiriとApp Intents",["OmniDateは一部の太陽情報にSiriとApp Intentsを使用できます。これらの処理に独自サーバーは使用しません。"]],["8. Apple Watch",["OmniDateはApple Watch機能とコンプリケーションを提供します。これらの利用によって開発者が追加の個人データを収集することはありません。"]],["9. 通知",["OmniDateは特定のイベントのローカル通知と、お気に入りの日付の年次リマインダーを端末上で設定できます。"]],["10. ウィジェット",["ホーム画面とロック画面のウィジェットは、OmniDateが端末上で動作するために必要な情報を使用します。開発者による個人データ収集は発生しません。"]],["11. トラッキング、広告、プロファイリング",["OmniDateは広告を含まず、アプリ間トラッキングや広告プロファイルの作成を行いません。"]],["12. Appleのサービス",["Appleは独自のポリシーとユーザー設定に従い、特定の技術情報を処理する場合があります。これはAppleのサービスによる処理です。"]],["13. 外部リンク",["OmniDateとサポートサイトにはWikipedia、Wikimedia、GitHubなど外部サービスへのリンクが含まれる場合があります。利用には各サービスのプライバシーポリシーが適用されます。"]],["14. 子ども",["OmniDateは子どもやその他のユーザーの個人データを意図的に収集しません。"]],["15. ポリシーの変更",["OmniDateの機能の進化に応じて、このポリシーは更新される場合があります。"]],["16. お問い合わせ",["ご質問はOmniDateサポートページをご利用ください。"]]]},"support":{"title":"サポート","intro":"OmniDateで問題が発生した、誤りを見つけた、改善案を提案したい場合、このページが公式サポート窓口です。","contact":"お問い合わせ","contactp":"サポート依頼は次のアドレスへ送信してください：","report":"問題を報告","view":"報告を見る","before":"問題を報告する前に","bullets":["iPhone、iPad、Apple Watchのモデルを記載してください。","iOS、iPadOS、watchOSのバージョンを記載してください。","OmniDateのバージョンを記載してください。","問題を再現する手順を説明してください。","表示上の問題では端末モデルと向きを記載してください。","日食・月食または流星群の問題では日付と選択した場所を記載してください。","歴史イベントの問題では日付、言語、可能であればタイトルを記載してください。"],"notice":"安全のため、公開の報告には個人情報、パスワード、機密情報を投稿しないでください。","faqtitle":"よくある質問","faqs":[["OmniDate 1.5.2の「今後のイベント」には何が含まれますか？","季節、月相、近地点、遠地点、スーパームーン、日食・月食、時刻変更、流星群、惑星の合と衝、水星と金星の離角、地球の近日点・遠日点、注目の彗星の通過が含まれます。"],["過去の日食・月食も見られますか？","はい。OmniDateは過去と未来の両方の日付を探索するためのアプリです。必要なデータが利用できる場合、歴史的な日食・月食も地図で確認できます。"],["日食・月食の地図には何が表示されますか？","種類に応じて、可視範囲、経路や境界、おおよその最大地点、選択地点で計算された状況などが表示されます。"],["流星群の地図には何が表示されますか？","放射点の位置、空の暗さ、月の影響に基づく幾何学的な観測条件を表示します。天気予報ではなく観測支援です。"],["「この日に何が起きた？」には何が含まれますか？","約20,000件の歴史イベントを収録したローカルデータベースがあります。カテゴリで絞り込み、個別に開き、完全な一覧で日ごとに閲覧できます。"],["PDFの日付シートはどう作成しますか？","共有ボタンをタップし「日付シートを作成」を選びます。日付、時刻、場所を入力し、暦を選択して、保存または共有する前にプレビューします。"],["OmniDateはなぜ位置情報を使うのですか？","太陽時刻、一部の月情報、地域ごとの日食・月食の可視性、特定の天文観測条件など、場所依存の情報に使用します。現在地、保存済みの場所、手動で選択した都市を利用できます。"],["OmniDateにアカウントは必要ですか？","いいえ。ユーザーアカウントは不要です。"]]},"rtl":false},"ko":{"name":"한국어","nav":{"home":"홈","support":"지원","privacy":"개인정보 보호"},"home":{"lead":"달력, 태양, 달, 역사와 천문학을 통해 모든 날짜를 탐색하세요. OmniDate 1.5.2은 유성우, 행성 배치, 지구 궤도 이벤트, 주요 혜성, 과거와 미래의 일식 및 월식에 대한 새로운 시각화를 추가해 천문 이벤트를 크게 확장했습니다.","pills":["15개 언어","약 20,000개의 역사적 사건","과거와 미래의 일식·월식","유성우","주요 혜성"],"cards":[["하나의 날짜, 여러 달력","같은 날을 그레고리력, 율리우스력, 프랑스 공화력, 중국력, 히브리력, 이슬람력, 페르시아력, 불교력, 일본력 및 ISO 8601에서 즉시 비교합니다."],["이 날짜에는 무슨 일이 있었나요?","약 20,000개의 역사적 사건이 담긴 로컬 데이터베이스를 탐색하세요. 카테고리로 필터링하고 세부 정보와 출처를 확인하며 날짜별로 이동할 수 있습니다."],["다가오는 천문 이벤트","계절, 달의 위상, 근지점, 원지점, 슈퍼문, 일식·월식, 시간 변경, 유성우, 행성 합, 충, 이각, 근일점, 원일점 및 주요 혜성 통과를 확인합니다."],["유성우","주요 유성우의 기하학적 관측 조건을 지도에서 확인하고 선택한 위치의 관측 가능성을 살펴봅니다."],["시간과 공간 속의 일식·월식","미래와 과거의 일식 및 월식을 탐색합니다. 전용 지도는 가시 영역과 현상에 따라 경로, 경계 및 지역 상황을 보여 줍니다."],["달과 달 관련 이벤트","달의 위상, 조명 비율, 월령, 지구-달 거리, 월출과 월몰, 고도, 방위각 및 다가오는 달 이벤트."],["태양의 움직임 추적","일출, 일몰, 태양 정오, 낮의 길이, 낮이나 밤의 진행도, 시민·항해·천문 박명."],["천문력과 점성술","이름 축일, 전통 속담, 국제 기념일과 OmniDate가 제공하는 점성술 정보를 확인합니다."],["PDF 날짜 시트","날짜, 시간과 장소로 날짜 시트를 만들고 달력, 태양, 달, 천문력, 점성술 정보를 모아 PDF로 저장하거나 공유합니다."],["즐겨찾는 날짜","중요한 날짜를 저장하고 빠르게 다시 열며 필요하면 연간 알림을 활성화합니다."],["사용자화 가능한 위젯","홈 화면과 잠금 화면 위젯을 설정해 원하는 달력과 정보를 표시합니다."],["Apple Watch","손목에서 OmniDate의 핵심 정보를 확인하고 전용 컴플리케이션을 사용합니다."]]},"privacy":{"title":"개인정보 처리방침","updated":"최종 업데이트: 2026년 10월 19일","notice":"OmniDate 1.5.2은 사용자 계정, 광고, 앱 간 추적 또는 개발자의 개인 데이터 수집 없이 작동하도록 설계되었습니다.","sections":[["1. OmniDate가 수집하는 데이터",["OmniDate는 계정을 요구하지 않으며 개발자가 운영하는 서버로 개인 데이터를 수집, 저장 또는 전송하지 않습니다."]],["2. 기기에 저장되는 데이터",["즐겨찾는 날짜, 이름, 표시 환경설정, 달력, 천문력 및 알림 설정 등 사용자가 저장한 앱 설정과 정보는 기기에 로컬로 저장됩니다."]],["3. 달력 및 천문 계산",["달력 변환과 태양, 달, 행성, 일식과 월식, 유성우, 지구 궤도 및 기타 천문 이벤트에 관한 대부분의 계산은 기기에서 로컬로 수행됩니다. OmniDate에 포함된 데이터도 로컬로 사용됩니다."]],["4. 역사적 사건 및 번역",["OmniDate에는 약 20,000개의 역사적 사건이 담긴 로컬 데이터베이스가 있습니다. 탐색, 필터링 및 이동은 기기에서 처리됩니다. Wikipedia/Wikimedia 링크는 사용자가 선택한 경우에만 열립니다.","일부 언어에서는 Apple의 번역 기능을 사용할 수 있습니다. 개발자는 번역된 텍스트나 번역 요청을 받지 않습니다."]],["5. 날짜 시트 및 PDF",["OmniDate는 날짜, 시간, 장소와 선택적 제목으로 날짜 시트를 만들 수 있습니다. 이 정보는 로컬로 사용됩니다. PDF 공유는 iOS 또는 iPadOS의 공유 기능과 사용자가 선택한 서비스를 사용합니다."]],["6. 위치 및 장소 검색",["현재 위치 사용을 선택하면 OmniDate는 위치에 따라 달라지는 정보, 즉 태양 데이터, 일부 달 정보, 지역별 일식·월식 가시성 및 특정 천문 관측 조건을 계산하기 위해 위치에 접근합니다.","OmniDate는 위치를 개발자 서버로 보내지 않습니다. Apple 시스템 서비스가 장소 검색이나 좌표에 도시 이름을 연결하는 데 사용될 수 있습니다. 저장된 장소나 수동으로 선택한 도시도 사용할 수 있습니다."]],["7. Siri 및 App Intents",["OmniDate는 일부 태양 정보에 Siri와 App Intents를 사용할 수 있습니다. 이러한 요청을 처리하기 위해 자체 서버를 사용하지 않습니다."]],["8. Apple Watch",["OmniDate는 Apple Watch 기능과 컴플리케이션을 제공합니다. 개발자는 이 기능 사용으로 추가 개인 데이터를 수집하지 않습니다."]],["9. 알림",["OmniDate는 특정 이벤트의 로컬 알림과 즐겨찾는 날짜의 연간 알림을 기기에서 예약할 수 있습니다."]],["10. 위젯",["홈 화면과 잠금 화면 위젯은 OmniDate가 기기에서 작동하는 데 필요한 정보를 사용합니다. 개발자가 개인 데이터를 수집하지 않습니다."]],["11. 추적, 광고 및 프로파일링",["OmniDate는 광고를 포함하지 않으며 앱 간 추적이나 광고 프로필 생성을 하지 않습니다."]],["12. Apple 서비스",["Apple은 자체 정책과 사용자가 선택한 설정에 따라 특정 기술 정보를 처리할 수 있습니다. 이러한 처리는 Apple 서비스의 일부입니다."]],["13. 외부 링크",["OmniDate 및 지원 사이트에는 Wikipedia, Wikimedia, GitHub 또는 기타 외부 서비스 링크가 포함될 수 있으며 각 서비스의 개인정보 정책이 적용됩니다."]],["14. 아동",["OmniDate는 아동이나 다른 사용자의 개인 데이터를 의도적으로 수집하지 않습니다."]],["15. 정책 변경",["OmniDate 기능이 발전함에 따라 이 정책이 업데이트될 수 있습니다."]],["16. 연락처",["문의 사항은 OmniDate 지원 페이지를 이용해 주세요."]]]},"support":{"title":"지원","intro":"OmniDate 사용 중 문제가 있거나 오류를 발견했거나 개선을 제안하고 싶다면 이 페이지가 공식 지원 창구입니다.","contact":"연락처","contactp":"지원 요청은 다음 이메일로 보내 주세요:","report":"문제 보고","view":"보고된 문제 보기","before":"문제를 보고하기 전에","bullets":["iPhone, iPad 또는 Apple Watch 모델을 적어 주세요.","iOS, iPadOS 또는 watchOS 버전을 적어 주세요.","OmniDate 버전을 적어 주세요.","문제를 재현하는 단계를 설명해 주세요.","표시 문제라면 기기 모델과 방향을 적어 주세요.","일식·월식 또는 유성우 문제라면 날짜와 선택한 위치를 적어 주세요.","역사적 사건 문제라면 날짜, 언어와 가능하면 제목을 적어 주세요."],"notice":"안전을 위해 공개 이슈에 개인정보, 비밀번호 또는 기밀 정보를 게시하지 마세요.","faqtitle":"자주 묻는 질문","faqs":[["OmniDate 1.5.2의 ‘다가오는 이벤트’에는 무엇이 포함되나요?","계절, 달의 위상, 근지점, 원지점, 슈퍼문, 일식과 월식, 시간 변경, 유성우, 행성의 합과 충, 수성과 금성의 이각, 지구의 근일점과 원일점, 주요 혜성 통과가 포함됩니다."],["과거의 일식과 월식도 탐색할 수 있나요?","예. OmniDate는 과거와 미래의 날짜를 모두 탐색하도록 설계되었습니다. 필요한 데이터가 있을 경우 역사적인 일식·월식을 지도에서 확인할 수 있습니다."],["일식·월식 지도는 무엇을 보여 주나요?","유형에 따라 가시 영역, 경로나 경계, 대략적인 최대 지점 및 선택한 위치에서 계산된 상황을 표시할 수 있습니다."],["유성우 지도는 무엇을 보여 주나요?","복사점 위치, 하늘의 어두움, 달의 영향에 따른 기하학적 관측 조건을 보여 줍니다. 날씨 예보가 아니라 관측 보조 도구입니다."],["‘이 날짜에는 무슨 일이 있었나요?’에는 무엇이 포함되나요?","약 20,000개의 역사적 사건이 담긴 로컬 데이터베이스가 있습니다. 카테고리로 필터링하고 개별적으로 열며 전체 목록에서 날짜별로 탐색할 수 있습니다."],["PDF 날짜 시트는 어떻게 만들나요?","공유 버튼을 누르고 ‘날짜 시트 만들기’를 선택합니다. 날짜, 시간, 장소를 입력하고 달력을 선택한 뒤 저장 또는 공유하기 전에 미리 봅니다."],["OmniDate는 왜 위치를 사용하나요?","태양 시간, 일부 달 정보, 지역별 일식·월식 가시성 및 특정 천문 관측 조건처럼 장소에 따라 달라지는 정보에 사용됩니다. 현재 위치, 저장된 장소 또는 수동으로 선택한 도시를 사용할 수 있습니다."],["OmniDate에 계정이 필요한가요?","아니요. 사용자 계정은 필요하지 않습니다."]]},"rtl":false},"ar":{"name":"العربية","nav":{"home":"الرئيسية","support":"الدعم","privacy":"الخصوصية"},"home":{"lead":"استكشف كل تاريخ من خلال التقاويم والشمس والقمر والتاريخ وعلم الفلك. يوسّع OmniDate 1.5.2 الأحداث الفلكية بشكل كبير مع زخات الشهب وتشكيلات الكواكب وأحداث مدار الأرض والمذنبات البارزة وتمثيلات جديدة للكسوف والخسوف في الماضي والمستقبل.","pills":["15 لغة","≈ 20,000 حدث تاريخي","كسوف وخسوف في الماضي والمستقبل","زخات الشهب","مذنبات بارزة"],"cards":[["تاريخ واحد، تقاويم متعددة","قارن اليوم نفسه فورًا عبر التقويم الميلادي واليولياني والجمهوري الفرنسي والصيني والعبري والإسلامي والفارسي والبوذي والياباني وISO 8601."],["ماذا حدث في هذا التاريخ؟","استكشف قاعدة بيانات محلية تضم نحو 20,000 حدث تاريخي. صفِّ حسب الفئة، وافتح الحدث للاطلاع على التفاصيل والمصادر، وتنقّل يومًا بعد يوم."],["الأحداث الفلكية القادمة","اعرض الفصول وأطوار القمر والحضيض والأوج والأقمار العملاقة والكسوف والخسوف وتغييرات الوقت وزخات الشهب واقترانات الكواكب ومقابلاتها والاستطالات وحضيض الأرض الشمسي وأوجها ومرور المذنبات البارزة."],["زخات الشهب","بالنسبة إلى أهم زخات الشهب، اعرض ظروف الرصد الهندسية على خريطة وافحص إمكانات الرصد من الموقع المحدد."],["الكسوف والخسوف عبر الزمان والمكان","استكشف الكسوف والخسوف الشمسي والقمري في المستقبل والماضي. تعرض الخرائط مناطق الرؤية، وبحسب الظاهرة المسار والحدود والظروف المحلية."],["القمر والأحداث القمرية","طور القمر وإضاءته وعمره والمسافة بين الأرض والقمر وشروق القمر وغروبه والارتفاع والسمت والأحداث القمرية القادمة."],["تابع مسار الشمس","شروق الشمس وغروبها والظهر الشمسي وطول النهار وتقدم النهار أو الليل والشفق المدني والبحري والفلكي."],["التقويم الفلكي وعلم التنجيم","اعرض أسماء القديسين والأمثال والأيام الدولية المتاحة، إلى جانب معلومات التنجيم التي يوفرها OmniDate."],["بطاقات التاريخ بصيغة PDF","أنشئ بطاقة من تاريخ ووقت ومكان. اجمع التقاويم والشمس والقمر والتقويم الفلكي وعلم التنجيم، ثم احفظ النتيجة أو شاركها بصيغة PDF."],["التواريخ المفضلة","احفظ التواريخ المهمة، وعد إليها بسرعة، وفعّل إشعارًا سنويًا إذا رغبت."],["أدوات قابلة للتخصيص","خصص أدوات الشاشة الرئيسية وشاشة القفل لعرض التقاويم والمعلومات التي تهمك."],["Apple Watch","اعرض معلومات OmniDate الأساسية على معصمك واستخدم المضاعفات المخصصة."]]},"privacy":{"title":"سياسة الخصوصية","updated":"آخر تحديث: 19 أكتوبر 2026","notice":"صُمم OmniDate 1.5.2 للعمل دون حساب مستخدم أو إعلانات أو تتبع بين التطبيقات أو جمع بيانات شخصية من قبل المطور.","sections":[["1. البيانات التي يجمعها OmniDate",["لا يتطلب OmniDate حسابًا ولا يجمع أو يخزن أو يرسل بيانات شخصية إلى خادم يديره المطور."]],["2. البيانات المخزنة محليًا",["تُحفظ إعدادات التطبيق والمعلومات التي تختار حفظها، بما في ذلك التواريخ المفضلة وأسماؤها وتفضيلات العرض وإعدادات التقويم والتقويم الفلكي والإشعارات، محليًا على جهازك."]],["3. حسابات التقويم والفلك",["تُجرى تحويلات التقويم ومعظم الحسابات المتعلقة بالشمس والقمر والكواكب والكسوف والخسوف وزخات الشهب ومدار الأرض والأحداث الفلكية الأخرى محليًا على الجهاز. وتُستخدم بيانات OmniDate المضمّنة محليًا."]],["4. الأحداث التاريخية والترجمة",["يتضمن OmniDate قاعدة بيانات محلية لنحو 20,000 حدث تاريخي. تتم المشاهدة والتصفية والتنقل على الجهاز. ولا تُفتح روابط Wikipedia/Wikimedia إلا عندما تختار ذلك.","قد يستخدم OmniDate ميزات الترجمة من Apple لبعض اللغات. لا يتلقى المطور النصوص المترجمة أو طلبات الترجمة."]],["5. بطاقات التاريخ وملفات PDF",["يمكن لـ OmniDate إنشاء بطاقة من تاريخ ووقت ومكان وعنوان اختياري. تُستخدم هذه المعلومات محليًا. وتستخدم مشاركة PDF ميزات المشاركة في iOS أو iPadOS والخدمة التي تختارها."]],["6. الموقع والبحث عن الأماكن",["عندما تختار استخدام موقعك الحالي، يصل OmniDate إلى الموقع لحساب معلومات تعتمد على المكان، بما في ذلك بيانات الشمس وبعض بيانات القمر وإمكانية رؤية الكسوف والخسوف محليًا وبعض ظروف الرصد الفلكي.","لا يرسل OmniDate موقعك إلى خادم يديره المطور. قد تُستخدم خدمات نظام Apple للبحث عن مكان أو ربط اسم مدينة بالإحداثيات. ويمكنك أيضًا استخدام مكان محفوظ أو مدينة مختارة يدويًا."]],["7. Siri وApp Intents",["يمكن لـ OmniDate استخدام Siri وApp Intents لبعض معلومات الشمس. ولا يستخدم خادمًا خاصًا لمعالجة هذه الطلبات."]],["8. Apple Watch",["يوفر OmniDate ميزات Apple Watch والمضاعفات. ولا يجمع المطور بيانات شخصية إضافية نتيجة استخدامها."]],["9. الإشعارات",["يمكن لـ OmniDate جدولة إشعارات محلية لأحداث محددة وتذكيرات سنوية للتواريخ المفضلة. وتُجدول على الجهاز وفق إعداداتك."]],["10. الأدوات",["تستخدم أدوات الشاشة الرئيسية وشاشة القفل المعلومات اللازمة لتشغيل OmniDate على الجهاز. ولا يؤدي استخدامها إلى جمع بيانات شخصية من قبل المطور."]],["11. التتبع والإعلانات وإنشاء الملفات الشخصية",["لا يتضمن OmniDate إعلانات ولا يجري تتبعًا بين التطبيقات ولا ينشئ ملفات تعريف إعلانية."]],["12. خدمات Apple",["قد تعالج Apple بعض المعلومات التقنية وفق سياساتها وإعدادات المستخدم. ويُعد ذلك جزءًا من خدمات Apple."]],["13. الروابط الخارجية",["قد يحتوي OmniDate وموقع الدعم على روابط إلى Wikipedia وWikimedia وGitHub أو خدمات خارجية أخرى. ويخضع استخدامها لسياسات الخصوصية الخاصة بها."]],["14. الأطفال",["لا يجمع OmniDate عن علم بيانات شخصية من الأطفال أو المستخدمين الآخرين."]],["15. تغييرات هذه السياسة",["قد يتم تحديث هذه السياسة مع تطور ميزات OmniDate."]],["16. الاتصال",["للاستفسارات، استخدم صفحة دعم OmniDate."]]]},"support":{"title":"الدعم","intro":"إذا واجهت مشكلة في OmniDate أو وجدت خطأ أو أردت اقتراح تحسين، فهذه الصفحة هي نقطة الدعم الرسمية للتطبيق.","contact":"الاتصال","contactp":"لطلب الدعم، راسل","report":"الإبلاغ عن مشكلة","view":"عرض البلاغات","before":"قبل الإبلاغ عن مشكلة","bullets":["اذكر طراز iPhone أو iPad أو Apple Watch؛","اذكر إصدار iOS أو iPadOS أو watchOS؛","اذكر إصدار OmniDate؛","صف الخطوات اللازمة لإعادة ظهور المشكلة؛","لمشكلة عرض، اذكر طراز الجهاز واتجاهه؛","لمشكلة تتعلق بكسوف أو خسوف أو زخات شهب، اذكر التاريخ والموقع المحدد؛","لمشكلة حدث تاريخي، اذكر التاريخ واللغة، وإذا أمكن عنوان الحدث."],"notice":"لأمانك، لا تنشر معلومات شخصية أو كلمات مرور أو بيانات سرية في بلاغ عام.","faqtitle":"الأسئلة الشائعة","faqs":[["ماذا يتضمن قسم «الأحداث القادمة» في OmniDate 1.5.2؟","يتضمن الفصول وأطوار القمر والحضيض والأوج والأقمار العملاقة والكسوف والخسوف وتغييرات الوقت وزخات الشهب واقترانات الكواكب ومقابلاتها واستطالات عطارد والزهرة وحضيض الأرض الشمسي وأوجها ومرور المذنبات البارزة."],["هل يمكنني استكشاف الكسوف والخسوف في الماضي؟","نعم. صُمم OmniDate لاستكشاف التواريخ الماضية والمستقبلية. ويمكن للخرائط دراسة الكسوف والخسوف التاريخي عندما تتوفر البيانات اللازمة."],["ماذا تعرض خرائط الكسوف والخسوف؟","بحسب النوع، قد تعرض مناطق الرؤية أو المسار أو الحدود ونقطة أقصى تقريبية والظروف المحسوبة لموقع محدد."],["ماذا تعرض خريطة زخات الشهب؟","تعرض ظروف الرصد الهندسية وفق موضع نقطة الإشعاع وظلام السماء وتأثير القمر. وهي أداة مساعدة للرصد وليست توقعًا للطقس."],["ماذا يتضمن «ماذا حدث في هذا التاريخ؟»","يتضمن OmniDate قاعدة بيانات محلية لنحو 20,000 حدث تاريخي. يمكن تصفيتها حسب الفئة وفتحها منفردة وتصفحها يومًا بعد يوم."],["كيف أنشئ بطاقة تاريخ PDF؟","اضغط زر المشاركة واختر «إنشاء بطاقة تاريخ». أدخل التاريخ والوقت والمكان، اختر التقاويم ثم عاين البطاقة قبل الحفظ أو المشاركة."],["لماذا يستخدم OmniDate الموقع؟","يُستخدم الموقع للمعلومات التي تعتمد على المكان، مثل أوقات الشمس وبعض معلومات القمر وإمكانية رؤية الكسوف والخسوف محليًا وبعض ظروف الرصد الفلكي. يمكنك استخدام موقعك الحالي أو مكان محفوظ أو مدينة تختارها يدويًا."],["هل يتطلب OmniDate حسابًا؟","لا. لا يلزم حساب مستخدم."]]},"rtl":true},"hi":{"name":"हिन्दी","nav":{"home":"होम","support":"सहायता","privacy":"गोपनीयता"},"home":{"lead":"कैलेंडर, सूर्य, चंद्रमा, इतिहास और खगोल विज्ञान के माध्यम से हर तारीख को जानें। OmniDate 1.5.2 उल्का वर्षा, ग्रहों की स्थितियों, पृथ्वी की कक्षा से जुड़े घटनाक्रम, प्रमुख धूमकेतुओं और अतीत व भविष्य के ग्रहणों के नए दृश्य के साथ खगोलीय घटनाओं का काफी विस्तार करता है।","pills":["15 भाषाएँ","≈ 20,000 ऐतिहासिक घटनाएँ","अतीत और भविष्य के ग्रहण","उल्का वर्षा","प्रमुख धूमकेतु"],"cards":[["एक तारीख, कई कैलेंडर","एक ही दिन को ग्रेगोरियन, जूलियन, फ्रांसीसी रिपब्लिकन, चीनी, हिब्रू, इस्लामी, फ़ारसी, बौद्ध, जापानी और ISO 8601 कैलेंडरों में तुरंत तुलना करें।"],["इस तारीख को क्या हुआ था?","लगभग 20,000 ऐतिहासिक घटनाओं का स्थानीय डेटाबेस देखें। श्रेणी से फ़िल्टर करें, विवरण और स्रोत खोलें और दिन-ब-दिन ब्राउज़ करें।"],["आने वाली खगोलीय घटनाएँ","ऋतुएँ, चंद्र कलाएँ, उपभू, अपभू, सुपरमून, ग्रहण, समय परिवर्तन, उल्का वर्षा, ग्रह संयोजन, विपक्ष, दीर्घताएँ, उपसौर, अपसौर और प्रमुख धूमकेतु मार्ग देखें।"],["उल्का वर्षा","मुख्य उल्का वर्षा के लिए मानचित्र पर ज्यामितीय अवलोकन स्थितियाँ देखें और चुने स्थान से अवलोकन की संभावना का आकलन करें।"],["समय और अंतरिक्ष में ग्रहण","भविष्य और अतीत के सूर्य व चंद्र ग्रहणों को देखें। मानचित्र दृश्यता क्षेत्र और घटना के अनुसार पथ, सीमाएँ और स्थानीय परिस्थितियाँ दिखाते हैं।"],["चंद्रमा और चंद्र घटनाएँ","चंद्र कला, प्रकाश, चंद्र आयु, पृथ्वी-चंद्र दूरी, चंद्रोदय और चंद्रास्त, ऊँचाई, दिगंश और आने वाली चंद्र घटनाएँ।"],["सूर्य की गति देखें","सूर्योदय, सूर्यास्त, सौर मध्याह्न, दिन की अवधि, दिन या रात की प्रगति तथा नागरिक, नौवहन और खगोलीय संध्या।"],["पंचांग और ज्योतिष","उपलब्ध संत दिवस, कहावतें और अंतरराष्ट्रीय दिवस तथा OmniDate की ज्योतिष जानकारी देखें।"],["PDF तारीख शीट","तारीख, समय और स्थान से एक शीट बनाएँ। कैलेंडर, सूर्य, चंद्रमा, पंचांग और ज्योतिष को एक साथ रखें और परिणाम को PDF में सहेजें या साझा करें।"],["पसंदीदा तारीखें","महत्वपूर्ण तारीखें सहेजें, उन्हें जल्दी खोलें और चाहें तो वार्षिक सूचना सक्रिय करें।"],["अनुकूलन योग्य विजेट","होम स्क्रीन और लॉक स्क्रीन विजेट में अपनी पसंद के कैलेंडर और जानकारी दिखाएँ।"],["Apple Watch","कलाई पर OmniDate की आवश्यक जानकारी देखें और समर्पित complications का उपयोग करें।"]]},"privacy":{"title":"गोपनीयता नीति","updated":"अंतिम अपडेट: 19 अक्टूबर 2026","notice":"OmniDate 1.5.2 को उपयोगकर्ता खाता, विज्ञापन, ऐप्स के बीच ट्रैकिंग या डेवलपर द्वारा व्यक्तिगत डेटा संग्रह के बिना काम करने के लिए बनाया गया है।","sections":[["1. OmniDate द्वारा एकत्र किया जाने वाला डेटा",["OmniDate के लिए खाते की आवश्यकता नहीं है और यह डेवलपर द्वारा संचालित सर्वर पर व्यक्तिगत डेटा एकत्र, संग्रहीत या भेजता नहीं है।"]],["2. स्थानीय रूप से संग्रहीत डेटा",["ऐप सेटिंग्स और आपके द्वारा सहेजी गई जानकारी, जैसे पसंदीदा तारीखें, उनके नाम, प्रदर्शन प्राथमिकताएँ, कैलेंडर, पंचांग और सूचना सेटिंग्स, आपके डिवाइस पर स्थानीय रूप से संग्रहीत होती हैं।"]],["3. कैलेंडर और खगोलीय गणनाएँ",["कैलेंडर रूपांतरण और सूर्य, चंद्रमा, ग्रह, ग्रहण, उल्का वर्षा, पृथ्वी की कक्षा और अन्य खगोलीय घटनाओं से जुड़ी अधिकांश गणनाएँ डिवाइस पर स्थानीय रूप से की जाती हैं। OmniDate में शामिल डेटा भी स्थानीय रूप से उपयोग होता है।"]],["4. ऐतिहासिक घटनाएँ और अनुवाद",["OmniDate में लगभग 20,000 ऐतिहासिक घटनाओं का स्थानीय डेटाबेस है। देखना, फ़िल्टर करना और नेविगेशन डिवाइस पर होता है। Wikipedia/Wikimedia लिंक केवल तभी खुलते हैं जब आप उन्हें चुनते हैं।","कुछ भाषाओं के लिए OmniDate Apple की अनुवाद सुविधाओं का उपयोग कर सकता है। डेवलपर को अनुवादित पाठ या अनुवाद अनुरोध प्राप्त नहीं होते।"]],["5. तारीख शीट और PDF",["OmniDate तारीख, समय, स्थान और वैकल्पिक शीर्षक से एक तारीख शीट बना सकता है। यह जानकारी स्थानीय रूप से उपयोग होती है। PDF साझा करने में iOS या iPadOS की साझाकरण सुविधाएँ और आपकी चुनी सेवा उपयोग होती है।"]],["6. स्थान और जगह खोज",["जब आप वर्तमान स्थान उपयोग करते हैं, OmniDate स्थान-निर्भर जानकारी की गणना के लिए लोकेशन का उपयोग करता है, जिसमें सूर्य डेटा, कुछ चंद्र डेटा, स्थानीय ग्रहण दृश्यता और कुछ खगोलीय अवलोकन स्थितियाँ शामिल हैं।","OmniDate आपका स्थान डेवलपर के सर्वर पर नहीं भेजता। स्थान खोजने या निर्देशांकों से शहर का नाम जोड़ने के लिए Apple सिस्टम सेवाओं का उपयोग हो सकता है। आप सहेजा हुआ स्थान या मैन्युअल रूप से चुना शहर भी इस्तेमाल कर सकते हैं।"]],["7. Siri और App Intents",["OmniDate कुछ सूर्य जानकारी के लिए Siri और App Intents का उपयोग कर सकता है। इन अनुरोधों के लिए OmniDate अपना सर्वर इस्तेमाल नहीं करता।"]],["8. Apple Watch",["OmniDate Apple Watch सुविधाएँ और complications प्रदान करता है। इनके उपयोग से डेवलपर अतिरिक्त व्यक्तिगत डेटा एकत्र नहीं करता।"]],["9. सूचनाएँ",["OmniDate चुनी घटनाओं के लिए स्थानीय सूचनाएँ और पसंदीदा तारीखों के लिए वार्षिक रिमाइंडर डिवाइस पर निर्धारित कर सकता है।"]],["10. विजेट",["होम स्क्रीन और लॉक स्क्रीन विजेट OmniDate के डिवाइस पर काम करने के लिए आवश्यक जानकारी का उपयोग करते हैं। इनके उपयोग से डेवलपर द्वारा व्यक्तिगत डेटा संग्रह नहीं होता।"]],["11. ट्रैकिंग, विज्ञापन और प्रोफाइलिंग",["OmniDate में विज्ञापन नहीं हैं, यह ऐप्स के बीच ट्रैकिंग नहीं करता और विज्ञापन प्रोफाइल नहीं बनाता।"]],["12. Apple सेवाएँ",["Apple अपनी नीतियों और उपयोगकर्ता की चुनी सेटिंग्स के अनुसार कुछ तकनीकी जानकारी संसाधित कर सकता है। यह Apple सेवाओं का हिस्सा है।"]],["13. बाहरी लिंक",["OmniDate और इसकी सहायता साइट में Wikipedia, Wikimedia, GitHub या अन्य बाहरी सेवाओं के लिंक हो सकते हैं। उनका उपयोग उनकी अपनी गोपनीयता नीतियों के अधीन है।"]],["14. बच्चे",["OmniDate जानबूझकर बच्चों या अन्य उपयोगकर्ताओं का व्यक्तिगत डेटा एकत्र नहीं करता।"]],["15. इस नीति में बदलाव",["OmniDate की सुविधाओं के विकसित होने पर यह नीति अपडेट हो सकती है।"]],["16. संपर्क",["प्रश्नों के लिए OmniDate सहायता पृष्ठ का उपयोग करें।"]]]},"support":{"title":"सहायता","intro":"यदि OmniDate में समस्या है, कोई त्रुटि मिली है या सुधार सुझाना चाहते हैं, तो यह ऐप का आधिकारिक सहायता पृष्ठ है।","contact":"संपर्क","contactp":"सहायता के लिए ईमेल करें:","report":"समस्या रिपोर्ट करें","view":"रिपोर्ट देखें","before":"समस्या रिपोर्ट करने से पहले","bullets":["अपना iPhone, iPad या Apple Watch मॉडल बताएं;","अपना iOS, iPadOS या watchOS संस्करण बताएं;","अपना OmniDate संस्करण बताएं;","समस्या दोहराने के चरण बताएं;","प्रदर्शन समस्या के लिए डिवाइस मॉडल और ओरिएंटेशन बताएं;","ग्रहण या उल्का वर्षा समस्या के लिए तारीख और चुना स्थान बताएं;","ऐतिहासिक घटना के लिए तारीख, भाषा और संभव हो तो शीर्षक बताएं।"],"notice":"सुरक्षा के लिए सार्वजनिक रिपोर्ट में व्यक्तिगत जानकारी, पासवर्ड या गोपनीय डेटा कभी पोस्ट न करें।","faqtitle":"अक्सर पूछे जाने वाले प्रश्न","faqs":[["OmniDate 1.5.2 में ‘आने वाली घटनाएँ’ में क्या शामिल है?","ऋतुएँ, चंद्र कलाएँ, उपभू, अपभू, सुपरमून, सूर्य और चंद्र ग्रहण, समय परिवर्तन, उल्का वर्षा, ग्रह संयोजन और विपक्ष, बुध व शुक्र की दीर्घताएँ, पृथ्वी का उपसौर और अपसौर तथा प्रमुख धूमकेतु मार्ग।"],["क्या मैं अतीत के ग्रहण देख सकता हूँ?","हाँ। OmniDate अतीत और भविष्य की तारीखों की खोज के लिए बनाया गया है। आवश्यक डेटा उपलब्ध होने पर ऐतिहासिक ग्रहणों का अध्ययन किया जा सकता है।"],["ग्रहण मानचित्र क्या दिखाते हैं?","ग्रहण के प्रकार के अनुसार वे दृश्यता क्षेत्र, पथ या सीमाएँ, अनुमानित अधिकतम बिंदु और चुने स्थान के लिए गणना की गई परिस्थितियाँ दिखा सकते हैं।"],["उल्का वर्षा का मानचित्र क्या दिखाता है?","यह रेडिएंट की स्थिति, आकाश की अंधकारता और चंद्रमा के प्रभाव के आधार पर ज्यामितीय अवलोकन स्थितियाँ दिखाता है। यह अवलोकन सहायता है, मौसम पूर्वानुमान नहीं।"],["‘इस तारीख को क्या हुआ था?’ में क्या शामिल है?","OmniDate में लगभग 20,000 ऐतिहासिक घटनाओं का स्थानीय डेटाबेस है। इन्हें श्रेणी से फ़िल्टर, अलग-अलग खोला और पूरी सूची में दिन-ब-दिन देखा जा सकता है।"],["PDF तारीख शीट कैसे बनाऊँ?","शेयर बटन टैप करें और ‘तारीख शीट बनाएँ’ चुनें। तारीख, समय और स्थान दर्ज करें, कैलेंडर चुनें और सहेजने या साझा करने से पहले पूर्वावलोकन करें।"],["OmniDate स्थान का उपयोग क्यों करता है?","स्थान का उपयोग जगह-निर्भर जानकारी के लिए होता है: सूर्य समय, कुछ चंद्र जानकारी, स्थानीय ग्रहण दृश्यता और कुछ खगोलीय अवलोकन स्थितियाँ। आप वर्तमान स्थान, सहेजा स्थान या मैन्युअल चुना शहर उपयोग कर सकते हैं।"],["क्या OmniDate के लिए खाता चाहिए?","नहीं। उपयोगकर्ता खाते की आवश्यकता नहीं है।"]]},"rtl":false},"tr":{"name":"Türkçe","nav":{"home":"Ana Sayfa","support":"Destek","privacy":"Gizlilik"},"home":{"lead":"Her tarihi takvimler, Güneş, Ay, tarih ve astronomi üzerinden keşfedin. OmniDate 1.5.2; meteor yağmurları, gezegen konumları, Dünya yörüngesi olayları, dikkat çekici kuyruklu yıldızlar ve geçmiş ile gelecekteki tutulmaların yeni görselleştirmeleriyle astronomik olayları önemli ölçüde genişletir.","pills":["15 dil","≈ 20.000 tarihsel olay","Geçmiş ve gelecekteki tutulmalar","Meteor yağmurları","Dikkat çekici kuyruklu yıldızlar"],"cards":[["Bir tarih, birçok takvim","Aynı günü Gregoryen, Jülyen, Fransız Cumhuriyet, Çin, İbrani, İslami, İran, Budist, Japon ve ISO 8601 takvimlerinde anında karşılaştırın."],["Bu tarihte ne oldu?","Yaklaşık 20.000 tarihsel olay içeren yerel veritabanını keşfedin. Kategoriye göre filtreleyin, ayrıntı ve kaynakları açın ve gün gün gezinin."],["Yaklaşan astronomik olaylar","Mevsimler, Ay evreleri, yerberi, yeröte, süperaylar, tutulmalar, saat değişiklikleri, meteor yağmurları, gezegen kavuşumları, karşı konumlar, uzanımlar, günberi, günötesi ve dikkat çekici kuyruklu yıldız geçişleri."],["Meteor yağmurları","Başlıca meteor yağmurları için geometrik gözlem koşullarını haritada görün ve seçilen konumdan gözlem potansiyelini değerlendirin."],["Zaman ve uzayda tutulmalar","Gelecekteki ve tarihsel Güneş ve Ay tutulmalarını keşfedin. Haritalar görünürlük alanlarını ve olaya göre yolu, sınırları ve yerel koşulları gösterir."],["Ay ve Ay olayları","Ay evresi, aydınlanma, Ay yaşı, Dünya-Ay mesafesi, Ay doğuşu ve batışı, yükseklik, azimut ve yaklaşan Ay olayları."],["Güneşin hareketini izleyin","Gün doğumu, gün batımı, güneş öğlesi, gün uzunluğu, gündüz veya gece ilerlemesi ve sivil, denizcilik ve astronomik alacakaranlık."],["Efemeris ve astroloji","Mevcut isim günlerini, geleneksel sözleri ve uluslararası günleri, ayrıca OmniDate’in sunduğu astroloji bilgilerini görüntüleyin."],["PDF tarih sayfaları","Tarih, saat ve yerden bir tarih sayfası oluşturun. Takvimleri, Güneş’i, Ay’ı, efemerisi ve astrolojiyi bir araya getirip sonucu PDF olarak kaydedin veya paylaşın."],["Favori tarihler","Önemli tarihleri kaydedin, hızla geri dönün ve isterseniz yıllık bildirim etkinleştirin."],["Özelleştirilebilir widget’lar","Ana Ekran ve Kilit Ekranı widget’larını istediğiniz takvim ve bilgileri gösterecek şekilde yapılandırın."],["Apple Watch","OmniDate’in temel bilgilerini bileğinizden görün ve özel komplikasyonları kullanın."]]},"privacy":{"title":"Gizlilik Politikası","updated":"Son güncelleme: 19 Ekim 2026","notice":"OmniDate 1.5.2 kullanıcı hesabı, reklam, uygulamalar arası izleme veya geliştirici tarafından kişisel veri toplama olmadan çalışacak şekilde tasarlanmıştır.","sections":[["1. OmniDate tarafından toplanan veriler",["OmniDate hesap gerektirmez ve geliştirici tarafından işletilen bir sunucuya kişisel veri toplamaz, saklamaz veya göndermez."]],["2. Yerel olarak saklanan veriler",["Favori tarihler, adları, görüntüleme tercihleri, takvim, efemeris ve bildirim ayarları dahil olmak üzere uygulama ayarları ve kaydettiğiniz bilgiler cihazınızda yerel olarak saklanır."]],["3. Takvim ve astronomi hesaplamaları",["Takvim dönüşümleri ile Güneş, Ay, gezegenler, tutulmalar, meteor yağmurları, Dünya yörüngesi ve diğer astronomik olaylarla ilgili hesaplamaların çoğu cihazda yerel olarak yapılır. OmniDate içindeki veriler de yerel olarak kullanılır."]],["4. Tarihsel olaylar ve çeviri",["OmniDate yaklaşık 20.000 tarihsel olay içeren yerel bir veritabanına sahiptir. Görüntüleme, filtreleme ve gezinme cihazda yapılır. Wikipedia/Wikimedia bağlantıları yalnızca siz seçtiğinizde açılır.","Bazı diller için OmniDate Apple’ın çeviri özelliklerini kullanabilir. Geliştirici çevrilmiş metinleri veya çeviri isteklerini almaz."]],["5. Tarih sayfaları ve PDF",["OmniDate tarih, saat, yer ve isteğe bağlı başlıktan bir tarih sayfası oluşturabilir. Bu bilgiler yerel olarak kullanılır. PDF paylaşımı iOS veya iPadOS paylaşım özelliklerini ve seçtiğiniz hizmeti kullanır."]],["6. Konum ve yer arama",["Mevcut konumunuzu kullanmayı seçtiğinizde OmniDate; güneş verileri, seçili Ay verileri, yerel tutulma görünürlüğü ve belirli astronomik gözlem koşulları gibi yere bağlı bilgileri hesaplamak için konuma erişir.","OmniDate konumunuzu geliştiricinin sunucusuna göndermez. Apple sistem hizmetleri bir yer aramak veya koordinatlarla şehir adını eşleştirmek için kullanılabilir. Kayıtlı bir yer veya elle seçilmiş şehir de kullanabilirsiniz."]],["7. Siri ve App Intents",["OmniDate seçili Güneş bilgileri için Siri ve App Intents kullanabilir. Bu istekleri işlemek için kendi sunucusunu kullanmaz."]],["8. Apple Watch",["OmniDate Apple Watch özellikleri ve komplikasyonlar sunar. Geliştirici bunların kullanımı nedeniyle ek kişisel veri toplamaz."]],["9. Bildirimler",["OmniDate seçili olaylar için yerel bildirimler ve favori tarihler için yıllık hatırlatıcılar planlayabilir. Bunlar ayarlarınıza göre cihazda planlanır."]],["10. Widget’lar",["Ana Ekran ve Kilit Ekranı widget’ları OmniDate’in cihazda çalışması için gerekli bilgileri kullanır. Kullanımları geliştirici tarafından kişisel veri toplanmasına yol açmaz."]],["11. İzleme, reklam ve profil oluşturma",["OmniDate reklam içermez, uygulamalar arası izleme yapmaz ve reklam profilleri oluşturmaz."]],["12. Apple hizmetleri",["Apple kendi politikaları ve kullanıcının seçtiği ayarlar doğrultusunda belirli teknik bilgileri işleyebilir. Bu işlemler Apple hizmetlerinin parçasıdır."]],["13. Harici bağlantılar",["OmniDate ve destek sitesi Wikipedia, Wikimedia, GitHub veya diğer harici hizmetlere bağlantılar içerebilir. Kullanımları kendi gizlilik politikalarına tabidir."]],["14. Çocuklar",["OmniDate çocuklardan veya diğer kullanıcılardan bilerek kişisel veri toplamaz."]],["15. Bu politikadaki değişiklikler",["OmniDate özellikleri geliştikçe bu politika güncellenebilir."]],["16. İletişim",["Sorularınız için OmniDate destek sayfasını kullanın."]]]},"support":{"title":"Destek","intro":"OmniDate ile ilgili bir sorun mu yaşıyorsunuz, hata mı buldunuz veya geliştirme mi önermek istiyorsunuz? Bu sayfa uygulamanın resmi destek noktasıdır.","contact":"İletişim","contactp":"Destek için e-posta gönderin:","report":"Sorun bildir","view":"Bildirimleri görüntüle","before":"Sorun bildirmeden önce","bullets":["iPhone, iPad veya Apple Watch modelinizi belirtin;","iOS, iPadOS veya watchOS sürümünüzü belirtin;","OmniDate sürümünüzü belirtin;","sorunu yeniden oluşturmak için gereken adımları açıklayın;","görüntüleme sorunu için cihaz modelini ve yönünü belirtin;","tutulma veya meteor yağmuru sorunu için tarihi ve seçilen konumu belirtin;","tarihsel olay sorunu için tarihi, dili ve mümkünse olay başlığını belirtin."],"notice":"Güvenliğiniz için herkese açık bir bildirimde kişisel bilgi, parola veya gizli veri paylaşmayın.","faqtitle":"Sık sorulan sorular","faqs":[["OmniDate 1.5.2’de ‘Yaklaşan Olaylar’ neleri içerir?","Mevsimler, Ay evreleri, yerberi, yeröte, süperaylar, Güneş ve Ay tutulmaları, saat değişiklikleri, meteor yağmurları, gezegen kavuşumları ve karşı konumları, Merkür ve Venüs uzanımları, Dünya’nın günberi ve günötesi ile dikkat çekici kuyruklu yıldız geçişleri."],["Geçmiş tutulmaları keşfedebilir miyim?","Evet. OmniDate geçmiş ve gelecek tarihleri keşfetmek için tasarlanmıştır. Gerekli veriler bulunduğunda tarihsel tutulmalar incelenebilir."],["Tutulma haritaları ne gösterir?","Tutulma türüne göre görünürlük alanlarını, olayın yolunu veya sınırlarını, yaklaşık maksimum noktasını ve seçilen konum için hesaplanan koşulları gösterebilir."],["Meteor yağmuru haritası ne gösterir?","Radyant konumu, gökyüzü karanlığı ve Ay etkisine göre geometrik gözlem koşullarını gösterir. Bu bir gözlem yardımcısıdır, hava tahmini değildir."],["‘Bu tarihte ne oldu?’ neleri içerir?","OmniDate yaklaşık 20.000 tarihsel olay içeren yerel bir veritabanına sahiptir. Kategoriye göre filtrelenebilir, tek tek açılabilir ve tam listede gün gün gezilebilir."],["PDF tarih sayfası nasıl oluşturulur?","Paylaş düğmesine dokunun ve ‘Tarih sayfası oluştur’u seçin. Tarih, saat ve yeri girin, takvimleri seçin ve kaydetmeden veya paylaşmadan önce önizleyin."],["OmniDate neden konum kullanır?","Konum, güneş saatleri, seçili Ay bilgileri, yerel tutulma görünürlüğü ve belirli astronomik gözlem koşulları gibi yere bağlı bilgiler için kullanılır. Mevcut konumunuzu, kayıtlı bir yeri veya elle seçtiğiniz bir şehri kullanabilirsiniz."],["OmniDate hesap gerektirir mi?","Hayır. Kullanıcı hesabı gerekli değildir."]]},"rtl":false}};
(function(){let lang=localStorage.getItem("omnidate-lang")||((navigator.language||"fr").toLowerCase().startsWith("zh-tw")||(navigator.language||"").toLowerCase().includes("hant")?"zh-Hant":(navigator.language||"fr").split("-")[0]);if(!I18N[lang])lang="fr";const s=document.getElementById("langSelect");function el(i){return document.getElementById(i)}function apply(l){if(!I18N[l])l="fr";lang=l;localStorage.setItem("omnidate-lang",l);document.documentElement.lang=l;document.documentElement.dir=I18N[l].rtl?"rtl":"ltr";if(s)s.value=l;const x=I18N[l];el("navHome").textContent=x.nav.home;el("navSupport").textContent=x.nav.support;el("navPrivacy").textContent=x.nav.privacy;el("footSupport").textContent=x.nav.support;el("footPrivacy").textContent=x.nav.privacy;window.renderPage&&window.renderPage(x);}if(s)s.addEventListener("change",e=>apply(e.target.value));apply(lang);window.applyOmniDateLanguage=apply;})();